INSERT INTO commentary_fts (unit_id,author,canonical_ref,language,content_type,content) VALUES
('vallabhacharya-sc:source:11.19','Vallabhācārya','gita.11.19','sa','commentary','।।11.19।।किञ्च अनादिमध्यान्तमिति। कालरूपमेतदाधिदैविकं तदाह -- शशिसूर्यनेत्रमिति। कालाभिमानिनौ शशिसूर्यौ नेत्रे यस्य। तथा सायङ्कालाभिमानी दीप्तो हुताशश्च वक्त्रेषु यस्य तं त्वां पश्यामि।'),
('vallabhacharya-sc:source:11.20','Vallabhācārya','gita.11.20','sa','commentary','।।11.20।।द्यावापृथिव्योः इत्यारभ्यचूर्णितैरुत्तमाङ्गैः [11।27] इत्यन्तं स्पष्टार्थम्।'),
('vallabhacharya-sc:source:11.21','Vallabhācārya','gita.11.21','sa','commentary','।।11.21।।Sri Vallabhacharya did not comment on this sloka.'),
('vallabhacharya-sc:source:11.22','Vallabhācārya','gita.11.22','sa','commentary','।।11.22।।Sri Vallabhacharya did not comment on this sloka.'),
('vallabhacharya-sc:source:11.23','Vallabhācārya','gita.11.23','sa','commentary','।।11.23।।Sri Vallabhacharya did not comment on this sloka.'),
('vallabhacharya-sc:source:11.24','Vallabhācārya','gita.11.24','sa','commentary','।।11.24।।Sri Vallabhacharya did not comment on this sloka.'),
('vallabhacharya-sc:source:11.25','Vallabhācārya','gita.11.25','sa','commentary','।।11.25।।Sri Vallabhacharya did not comment on this sloka.'),
('vallabhacharya-sc:source:11.26','Vallabhācārya','gita.11.26','sa','commentary','।।11.26।।Sri Vallabhacharya did not comment on this sloka.'),
('vallabhacharya-sc:source:11.27','Vallabhācārya','gita.11.27','sa','commentary','।।11.27।।Sri Vallabhacharya did not comment on this sloka.'),
('vallabhacharya-sc:source:11.28','Vallabhācārya','gita.11.28','sa','commentary','।।11.28 -- 11.29।।यथा नदीनामिति। अम्बुवेगाः समुद्रमिव ते वक्त्राण्यभिमुखं तत्रैव चेमे नरलोकवीरा नाशाय विशन्ति।'),
('vallabhacharya-sc:source:11.29','Vallabhācārya','gita.11.29','sa','commentary','।।11.28 -- 11.29।।यथा नदीनामिति। अम्बुवेगाः समुद्रमिव ते वक्त्राण्यभिमुखं तत्रैव चेमे नरलोकवीरा नाशाय विशन्ति।'),
('vallabhacharya-sc:source:11.30','Vallabhācārya','gita.11.30','sa','commentary','।।11.30।।तान् लेलिह्यसे। हे विष्णो व्यापनशील अन्यत् स्पष्टम्।'),
('vallabhacharya-sc:source:11.31','Vallabhācārya','gita.11.31','sa','commentary','।।11.31।।अतस्त्वमाख्याहि। को भवानुग्ररूपो दृश्यसे हे देववर प्रसीदेति स्वस्य भीतत्वं सूचयति। एवं च त्वामाद्यं पुरुषं भयङ्कराकारेण वर्तमानं सर्वविलक्षणं विज्ञातुमिच्छामि यतस्तव प्रवृत्तिं च न जानामि ततो ब्रूहि।'),
('vallabhacharya-sc:source:11.32','Vallabhācārya','gita.11.32','sa','commentary','।।11.32।।एवं प्रार्थितः श्रीभगवानुवाच -- कालोऽस्मीति त्रिभिः। योऽधुनाऽऽविर्भूतः स कालोऽहम्। चतुर्धा ह्यहं अक्षरकालकर्मस्वभावभेदादित्यक्षरमपि लेलिहानत्वादिधर्मवत्त्वेन लिङ्गेन मां कालरूपमवेहि। यथोक्तं श्रीभागवते -- अन्तः पुरुषरूपेण कालरूपेण यो बहिः। समन्वेत्येष सत्त्वेन (सत्त्वानां) भगवानात्ममायया। तथावीर्याणि तस्याखिलदेहभाजामन्तर्बहिः पूरुषकालरूपैः। प्रयच्छतो मृत्युमुतामृतं च मायामनुष्यस्य वदस्व विद्वन् [भाग.10।1।7] कालरूपतयाऽसुरावेशिनां मृत्युहेतुरित्याह -- लोकानसुरावेशिन इह समाहर्त्तुं प्रवृत्त इति। अयमेव सङ्कर्षणभावः प्रदर्श्यते भगवता। संहारको हि सङ्कर्षणव्यूहः तत्केशस्य भगवत्स्वरूपेऽवतरणं भूमौ भारहरणार्थमिति भारते निरूप्यते। तथा च भूभारभूतानामेव संहारकः कालः प्रवृत्तोऽस्मि।ऋतेऽपि त्वां इत्युपलक्षणं मदनुगृहीतान्विना सर्वान्समाहर्तुं प्रवृत्तोऽस्मीत्यर्थः। त्वा हनननिमित्तभूतं विना न जीविष्यन्तीति वा सम्बन्धः। हे पार्थ त्वया न हन्तव्याश्चेन्मया कालरूपेण तु ग्रस्ताः तिरोभावं यास्यन्तीत्यभिप्रायेणन भविष्यन्ति इति प्रत्युक्तम्।'),
('vallabhacharya-sc:source:11.33','Vallabhācārya','gita.11.33','sa','commentary','।।11.33।।तस्मात्त्वमुत्तिष्ठ निमित्तमात्रं तु भव।'),
('vallabhacharya-sc:source:11.34','Vallabhācārya','gita.11.34','sa','commentary','।।11.34।।पूर्वशङ्काऽधुना न कार्येत्याह -- द्रोणमिति। येभ्यस्त्वं पूर्वमशङ्किथास्तानेतान् मया हतप्रायान्कालदृष्ट्या प्रारब्धकर्मणा जीवितशेषान् जहि। एवं रणे सपत्नान् जेष्यसि। ततो युद्धधर्मं कुरु।'),
('vallabhacharya-sc:source:11.35','Vallabhācārya','gita.11.35','sa','commentary','।।11.35।।ततो यत् जातं तदवसन्नाय धृतराष्ट्राय सञ्जय उवाच -- एतदिति। श्रुत्वा अर्जुन उवाचेति।'),
('vallabhacharya-sc:source:11.36','Vallabhācārya','gita.11.36','sa','commentary','।।11.36।।स्थाने इत्येकादशभिः प्रार्थयन्नाह फाल्गुनः। षड्भिर्गुणैस्त्रिभिर्युक्तं भगवन्तं गुणातिगम्।।स्थाने इत्यत्र प्रकीर्त्या युतं प्रार्थयति।स्थाने इत्यव्ययम्। युक्तमित्यर्थः। जगत्सर्वमनुरज्यते प्रहृष्यति च तव प्रकीर्त्या। अहं त्वधुना बिभेमीति द्योतयति। अयं श्लोको रक्षोघ्नमन्त्रशास्त्रे प्रसिद्धः।'),
('vallabhacharya-sc:source:11.37','Vallabhācārya','gita.11.37','sa','commentary','।।11.37।।कस्माच्चेति। ऐश्वर्यं वैराग्यं वा ब्रह्मणः समष्टिपुरुषजीवस्यादिकर्तृत्वेनालिप्तत्वात्सदसत्परमक्षरं इति नित्यत्वेन क्षरणाभावान्निरतिशयैश्वर्यं सर्वविभिन्नधर्माश्रयं त्वमेव ब्रह्मेत्याह। परं कारणम्।'),
('vallabhacharya-sc:source:11.38','Vallabhācārya','gita.11.38','sa','commentary','।।11.38।।त्वमिति। ज्ञानं वेत्तासि वेद्यं चेति विरुद्धधर्माश्रयत्वमक्षरत्वं च पुनः स्फोटयति -- परं धामेति।तद्धाम परमं मम [8।2115।6] इत्यनेनैकार्थ्यमेति।त्वया ततं विश्वं इति व्याख्यानभूतंमया ततमिदं सर्वं जगदव्यक्तमूर्तिना [9।4] इत्यादेः।'),
('vallabhacharya-sc:source:11.39','Vallabhācārya','gita.11.39','sa','commentary','।।11.39।।वायुर्यम इति सर्वरूपत्वेऽप्येकस्याव्ययत्वमित्यैश्वर्यं वैराग्यं वा अतस्ते सहस्रकृत्वो नमो नम इति सभयं प्रणमति।'),
('vallabhacharya-sc:source:11.40','Vallabhācārya','gita.11.40','sa','commentary','।।11.40।।सर्वरूपत्वेन वीर्यं तस्योपपादयति -- परं ब्रह्म तु कृष्णो हि सच्चिदानन्दकं बृहत्। द्विरूपं तद्धि सर्वं स्यादेकं तस्माद्विलक्षणम् इति वाक्यैरेकमपि तत्सर्वमित्याशयेनानन्तवीर्य हे सर्वेति सम्बोधयति। विश्वं व्याप्नोषि सर्वप्रपञ्चरूपस्त्वमेवेत्यर्थः।'),
('vallabhacharya-sc:source:11.41','Vallabhācārya','gita.11.41','sa','commentary','।।11.41।।अक्षरैश्वर्यादिगुणमहिमानं परमं तं दृष्ट्वा क्षमापयति -- सखेति। तव महिमानं अलौकिकमाहात्म्यश्रियं अतिशयेनाजानता मया यदुक्तं हे यादव हे सखेति तत्क्षामये त्वामित्यग्रिमेणान्वयः।'),
('vallabhacharya-sc:source:11.42','Vallabhācārya','gita.11.42','sa','commentary','।।11.42।।किञ्च तामसकर्मसु मृगयाविहारादिषु स्थितं त्वां तमोगुणयुक्तं पूर्वं ज्ञात्वा मया यदसत्कृतोऽसि तदप्येकोऽहं त्वां साम्प्रतं क्षमां कारयामि।'),
('vallabhacharya-sc:source:11.43','Vallabhācārya','gita.11.43','sa','commentary','।।11.43।।पिताऽसीति। पूज्यो गुरुश्चेति सात्त्विकोऽश्वमेधे राजसूये च विदितस्त्वं सात्त्विकधर्माणां त्वयि निरूपितत्वात्तथाभूतं त्वां जानन् क्षमापयेऽहं प्राकृतः।'),
('vallabhacharya-sc:source:11.44','Vallabhācārya','gita.11.44','sa','commentary','।।11.44।।यस्मादेवं? तस्मादिति। त्वामीशं सर्वेषां राजानं नियन्तारं रजोभावमाश्रितं भक्तवात्सल्येन सारथ्ये कर्मणि स्थितं प्रणम्य प्रसादये। त्वं च पितेव पुत्रस्य? सखेव सख्युः? प्रिय इव प्रियाय सर्वं सोढुमर्हसि।'),
('vallabhacharya-sc:source:11.45','Vallabhācārya','gita.11.45','sa','commentary','।।11.45।।एवं क्षमापयित्वा गुणातिगं प्रति प्रार्थयते -- अदृष्टेति। वस्तुतस्तु त्वं गुणातीत इति भक्ताय तदेव गुणातीतं रूपं प्रदर्शय। इदं चादृष्टपूर्वं ते रूपं दृष्ट्वा? पूर्वं दृष्टः पश्चाल्लोकान् ग्रसमानं ज्ञात्वा मनो मे प्रव्यथितं यतः? अतस्तदेव चतुर्भुजं वा दृष्टपूर्वं रूपं मे प्रदर्शय। अस्माकं तु चतुर्भुजं मर्यादामयं शुद्धसत्त्वात्मकं ते रूपं श्रेष्ठं शान्तत्वादित्याशयेनाह तद्दर्शने प्रसीदेति। अनेनाक्षरब्रह्मोपासकेभ्यः शुद्धसत्त्वमयचतुर्भुजोपासकामर्यादया गुणज्ञाः उत्तमा इति लभ्यते।'),
('vallabhacharya-sc:source:11.46','Vallabhācārya','gita.11.46','sa','commentary','।।11.46।।तदेव रूपं विशेषयन् भगवन्तं प्रार्थयते -- किरीटिनमिति। तदनेन श्रीकृष्णं अर्जुन एवमेव षड्गुणगणालङ्कृतं चतुर्भुजं पश्यति स्मेति गम्यते। द्विभुजं तु सदैवेति। न पुष्टिमिश्रमभक्तस्य जायते निर्भया रुचिः। स्वतः प्रवृत्तिजनिकाक्षरमात्रैकदर्शने। क्षराक्षरातीतहरे रसानन्दमहोदधेः। स्वरूपामृतमग्नानां नान्यत्र स्याद्रतिः क्वचित्। इत्यभिप्रायमाज्ञाय गोपानामिव तस्य च। आश्वासयन् भीतमेनमुवाच भगवान्पुनः।'),
('vallabhacharya-sc:source:11.47','Vallabhācārya','gita.11.47','sa','commentary','।।11.47।।श्रीभगवानुवाच -- मयेति त्रिभिः। मया सर्वमूलरूपेण स्वयं भगवतांऽशिना कृष्णेन स्वोपनिषत्प्रतिपाद्यस्वरूपेण द्विभुजेन लावण्यजलधिना महामनोरमेन गुणातीतेन सर्ववेदान्तवेद्यचरणेन परतत्त्वेन स्वाश्रितवात्सल्यकरुणावरुणालयेनाचिन्त्यैश्वरयोगेन प्रसन्नेन स्वात्मयोगबलात् परमुत्तमेततदक्षरं विश्वरूपं दर्शितम्। अनेन सदानन्दरूपे श्रीकृष्णे तस्मिन् द्विभुज एवेदं सामर्थ्यं यत्स्वरूपान्तरदर्शनमिति मूलरूपतयाऽवतारित्वादिति ज्ञापितम्। इत्थमेवोक्तभियुक्तैः -- नान्यावतारे सामर्थ्यं यत्कृष्णतनुदर्शनम्। श्रीकृष्ण एव सामर्थ्यं यद्रूपान्तरदर्शनम् इति।'),
('vallabhacharya-sc:source:11.48','Vallabhācārya','gita.11.48','sa','commentary','।।11.48।।मदनुग्रहैकलभ्यभक्तिव्यतिरिक्तैस्तु सर्वैरप्युपायैरेवमपि द्रष्टुमशक्य इत्याह -- न वेदेति। अहं पुरुषोत्तमः कृष्ण एवंरूपमैश्वरं यस्य स विशिष्टो नृलोके द्रष्टुमशक्यः केवलोऽक्षरादिस्तु स्वोपासकानां वेदप्रवचनादिसाधनैर्द्रष्टुं शक्योऽपि भवति? नाहं पुरुषोत्तमः अनन्यभक्तिलभ्यत्वात्भक्त्याऽहमेकया ग्राह्यः इति [11।14।21] भागवतवाक्यात्। तत्रापि त्वत्तो मदनुगृहीताद्भक्तादन्ये नैवमपि द्रष्टुं न शक्ताः एतद्दर्शनस्यापि मदनुग्रहलभ्यत्वात् त्वं तु केवलं मदनुग्रहात् दृष्टवानसि। इयमेव पुष्टिःपोषणं तदनुग्रहः इति [2।10।4] भागवतवाक्यात्।तद्रहितानामपि स्वप्रमेयबलेन स्वप्रापणं पुष्टिः इति भाष्यकारः। दैवस्य निग्रहणमनु सर्वसाधनकरणेनापि पुरुषोत्तमस्वरूपालाभे दैन्येनार्त्ततया च दृढतरबीजरूपासक्तिभावमनुग्रहणं भगवता यत्र भवति सोऽनुग्रहश्च पुष्टिरिति सङ्क्षेपः। तदिदं प्रमेयवर्त्म भागवतषष्ठस्कन्धे -- सध्रीचीनो ह्ययं पन्था लोके,क्षेमोऽकुतोऽभयः [अ.1।17] इति शुकेन धर्मविष्णुदूतसंवादोपाख्यानद्वारा स्पष्टमेव दर्शितमिति ततोऽवसेयम्। अत्रोपपत्तिर्भक्तिहेतुग्रन्थेऽनेकधा निरूपिता द्रष्टव्या।'),
('vallabhacharya-sc:source:11.49','Vallabhācārya','gita.11.49','sa','commentary','।।11.49।।किञ्च मा ते व्यथादिर्भवतु। घोरमिदं रूपं? कालरूपत्वात्। तव पुष्टिमिश्रमर्यादाभक्तस्य भयावहमिति तदेव पूर्वं दृष्टभूतं ममेदं पश्य।'),
('vallabhacharya-sc:source:11.50','Vallabhācārya','gita.11.50','sa','commentary','।।11.50।।एवं सञ्जय उवाच -- इतीति। स्वकं पूर्वं प्रदर्शितरूपं चतुर्भुजं दर्शयामास। तथापि सख्यसारथ्यादिकमनुचितं मत्वा रथादुत्तीर्य स्तोतुकामं पार्थमवलोक्य पुनः सौम्यवपुर्द्विभुज एव लोके सम्मत -- (संभवत्) -- स्वरूप एव भक्तप्रार्थनया भूत्वा पुरुषोत्तमोऽचिन्त्ययोगेश्वरो विभुर्महात्मा भीतमेनं आश्वासयामास। अत्र सौम्यपदमेव सर्वापेक्षया भयाभावसूचकं द्विभुजरूपं प्रत्याययति। अन्यथाभूयः पुनश्च इति पौनरुक्त्यं स्यात्। वदति चाग्रेदृष्ट्वेदं मानुषं रूपं [11।51] इति।'),
('vallabhacharya-sc:source:11.51','Vallabhācārya','gita.11.51','sa','commentary','।।11.51।।ततो यथावदवस्थितः सन् अर्जुन उवाच -- दृष्ट्वेदमिति। निरवधिकातिशयसौन्दर्यसौकुमार्यलावण्यसौशील्यादियुक्तं सदानन्दमात्रकरपादमुखोदरादिरूपं सौम्यं मानुषं मनुष्यत्वसंस्थानस्थितं दृष्ट्वा सचेताः जातोऽस्मि। तदा तु विचेताः अमनाः अपाणिपादं तदमूर्त्तमव्ययम् इति वाक्यात्। इदानीं तु प्रकृतिं स्वभावं प्राप्तोऽस्मि।'),
('vallabhacharya-sc:source:11.52','Vallabhācārya','gita.11.52','sa','commentary','।।11.52।।ततः एवं स्थितौ स्वरूपस्य सुदुर्दर्शत्वं निरूपयन्प्रसङ्गादनुग्रहभक्त्यैकगम्यत्वं स्वस्य निगमयति त्रिभिः -- सुदुर्दर्शमिति। इदं मत्सम्बन्धि रूपमक्षरं विश्वरूपं यत्त्वं दृष्टवानसि? यतोऽहं सुदुर्दर्शस्तदा किं वाच्यं मत्सम्बन्धिरूपमिदमिति तदेवाह -- देवा अपीति। सात्विका अपि ते नित्यं दर्शनकाङ्क्षिणः? न तु दृष्टवन्तोऽपि अनुग्रहबीजभावाभावात्।'),
('vallabhacharya-sc:source:11.53','Vallabhācārya','gita.11.53','sa','commentary','।।11.53।।एवं विश्वरूपस्य सुदुर्दर्शत्वं निरूप्य तदादिदृष्टस्य स्वस्यापि तदाह -- नाहं वेदैरिति। निरतिशयाक्षरैश्वर्योऽहमात्मा नायमात्मा प्रवचनेन लभ्यो न मेधया न बहुना श्रुतेन। यमेवैष वृणुत (सः) तेन लभ्यस्तस्यैष आत्मा (वि) वृणुते तनूं स्वाम् [कठो.2।22मुंडको.3।2।2] इति वरणेतरसाधनैरशक्यः श्रुतोऽस्मि। एवंविधं मां त्वं यत् वरणेन सत्प्रकारेण स्वरूपयोग्यो दृष्टवानसि तथा च प्रवचनादिसाधनानां केवलात्मसाक्षात्कारपरतया जीवे स्वरूपयोग्यतासम्पादकत्वं? न साक्षात्पुरुषोत्तमनिरोधकत्वमिति सिद्धम्।'),
('vallabhacharya-sc:source:11.54','Vallabhācārya','gita.11.54','sa','commentary','।।11.54।।तादृशे जीवे स्वीयत्वेन वरणे सञ्जातया भक्त्याऽहं भगवान् ग्राह्य इति तदाह -- भक्त्येति। अथवा ननु तर्हि सर्वैः कथमेवं दृश्यसे इति चेत्तत्राह -- भक्त्येति। सर्वनिरोधार्थमवतीर्णस्यापि मम दर्शनं ज्ञानं च केषाञ्चिन्मानुषत्वेनांशत्वादिना च भवति? न तु तत्त्वेन यतोऽहं तत्त्वेन ज्ञातुं द्रष्टुं हृदि प्रवेष्टुं च भक्त्यैव शक्यः। किम्भूतया अनन्ययेति। वेदप्रवचनादिसाधननिरपेक्षया मदनुग्रहिसङ्गैकलभ्यया रागानुगयेति यावत्।केचित्केवलया भक्त्या इति वाक्यात् प्रमेयरूपया तथेति। यतोऽहमेवंविधः। भक्त्या ग्राह्यःअस्वतन्त्र इव द्विजः इति। अथवा विश्वरूपाद्यक्षरैश्वर्यादियोगयुक्त एवाक्लिष्टकर्मा प्रवाहमर्यादापुष्टिप्रणेताऽलौकिकगुणगणो महामनोरमवपुर्महाकरुणोऽहं पुरुषोत्तमोऽपि।'),
('vallabhacharya-sc:source:11.55','Vallabhācārya','gita.11.55','sa','commentary','।।11.55।।यद्यप्येवं तथापि त्वादृशस्य मन्निगममर्यादायामनुगृहीतत्वान्मदाज्ञया मद्भक्तिपूर्वकमेव स्वधर्मकरणे मत्प्राप्तिरित्याह -- मत्कर्मकृदिति। भगवदीयस्य भगवत्सेवापूर्वककर्मकरणं विहितंमम कर्मकरणे प्रभोरिच्छाऽस्तीति यो निर्द्धारयति स करोति? य एतद्विपरीतं स न करोति? यथा शुकजडादिः। एतन्निर्द्धारश्च भगवदधीनोऽतो भक्तेष्वपि तन्निर्द्धारणानियम इत्यतः कर्म कर्त्तव्यमेव अतन्निर्द्धारणे त्वाधुनिकानाम् एवं सतीच्छाज्ञानवता तत्सन्देहवता च कर्त्तव्यं इति।तन्निर्द्धारणानियमः पृथग्यः प्रतिबन्धः फलं इत्यादि सूत्रभाष्ये निर्णीतमवगन्तव्यम्। मत्परम इति अहमेव परम उद्देश्यो यस्य परमो मद्भक्तः स मामेति पुरुषोत्तमाप्तिस्तस्य फलं भवतीत्यर्थः।'),
('vallabhacharya-sc:source:12.1','Vallabhācārya','gita.12.1','sa','commentary','।।12.1।।प्रमेयरूपा तद्भक्तिः प्रमेयः पुरुषोत्तमः। अतः प्रमेयमार्गे तु हरिः सेव्यो न चापरः।।1।।अथ पूर्वत्रयदक्षरं वेदविदो वदन्ति [8।11] इत्यादिना विश्वरूपादेरप्यक्षरत्वेन निरूपणश्रवणादक्षरस्य च भगवद्धामपदत्वोक्तौ भेदमिवालक्ष्य तदुभयोपासकविशेषजिज्ञासया भगवन्तमर्जुन उवाच -- एवमिति।मत्कर्मकृत् [11।55] इत्यादिनोक्तप्रकारेण सततं युक्ता योगिनोऽर्पितात्मानो वा भक्ता ये त्वां पुरुषोत्तमं सौम्यरूपं भक्तानुग्रहविग्रहं सर्वविभूतिमूलं निरवधिकातिशयसौन्दर्यसौशील्यसर्वज्ञत्वसत्यसङ्कल्पत्वाद्यनन्तगुणनिधिं सदानन्दमात्रकरपादमुखोदगङ्गं परिपूर्णं स्वेच्छयाऽधिदैविकश्रीभूलीलादिशक्तिभिः सह भुवि प्रादुर्भूतं स्वमायया मानुषाकारं पर्युपासते परिरत्र वर्जनेअपपरी वर्जने [अष्टा.1।4।88] इत्यनुशासनात्। अन्योपासनं परिवर्ज्य त्वत्समीप आसते आसक्ता ये भक्ताः। ये चापि समनन्तरोक्तरूपमक्षरमव्यक्तं पर्युपासते। तेषामुभयेषां मध्ये तव मताः के युक्ततमाः इति प्रश्नः।'),
('vallabhacharya-sc:source:12.2','Vallabhācārya','gita.12.2','sa','commentary','।।12.2।।तत्र सिद्धान्तं वदन् श्रीभगवानुवाच -- मयीति। सर्वनियन्तरि सकलालौकिकगुणे साक्षान्मन्मथमन्मथे निरवद्या(ध्य)नन्तनित्यलोके करुणाशीले परमानन्दे लोकोत्तरनामरूपाङ्गेऽसङ्ख्येयसर्वधर्माश्रये परतत्त्वे रसात्मके पूर्णपुरुषोत्तमे साक्षात्कर्त्तरि परदेवतायां भगवति सर्वमूलभूते मयि ये प्रेममात्रसम्बन्धेन (येनकेन च सम्बन्धेन) नित्ययुक्ता मन आवेश्य मामुपासते।अयमेवास्माकं भजनीयगुणालयः परः प्रेयानात्मा? नान्यः इति परया श्रद्धयोपेतास्ते युक्ततमा मे मताः।'),
('vallabhacharya-sc:source:12.3','Vallabhācārya','gita.12.3','sa','commentary','Sri Vallabhacharya did not comment on this sloka'),
('vallabhacharya-sc:source:12.4','Vallabhācārya','gita.12.4','sa','commentary','।।12.3 -- 12.4।।येत्विति। तुशब्दो भेदं द्योतयति। ये त्वक्षरमन्तर्यामिस्वरूपांशं पूर्वोक्तमनामरूपत्वादव्यक्तं गणितानन्दं बृहत्स्वरूपं पर्युपासते। स्वष्ट एव भेदः। अक्षरोऽव्यक्तः? अहं तु व्यक्तः। सोऽनिर्देश्यः? अहं तु स्वेच्छयाऽलौकिकनिर्देशार्हः। स सर्वत्रगः? अहं तु भक्तैकगम्यः। स चाचिन्त्यः अहं तु भक्तैश्चिन्त्यः। स तु कूटस्थः सर्वसाधारणः अहमसाधारणः। स त्वचलः स्थिरात्मा? अहं चलः तत्रतत्र विहरन् चलामि। स तु ध्रुवं पदरूपमैश्वर्यमध्यात्मं? अहं त्वीश्वरस्तन्निलयन इति। तदुपासका मां ब्रह्मानन्दात्मिकां श्रियमेव ध्रुवात्मानं वा मां प्राप्नुवन्ति।'),
('vallabhacharya-sc:source:12.5','Vallabhācārya','gita.12.5','sa','commentary','।।12.5।।तेषां तथाऽव्यक्ततया प्राप्तिरेव मत्स्वरूपस्य? न च तदधिगमपूर्वकं सुखमपीत्याह -- इह क्लेशोऽधिकतरो दुःखमव्यक्ता गतिरिति। तत्रापि सर्वभूतहिते रता एव तदा तथा मां प्राप्नुवन्ति। अनेन भागवतैकादशस्कन्धे भक्तस्वरूपनिरूपणे सर्वभूतहिते रतस्य भगवदात्माप्तिरुक्ता? नान्यस्य? तथेहापीत्युक्तं भवति। ततो देह इव देहवतां मदव्यक्तदेहासक्तचेतसां न तदन्तस्थितस्यात्मनो मम प्राप्तिः साक्षाद्रसानन्दरूपा? किन्तु दुःखमव्यक्तगतिरेव स्वरूपसहानिरैक्यं लवणस्य सलिल इवेति भावः। किञ्च तदुपासनकालेऽपि साधनक्लेशोऽधिकतरः? निर्विशेषे तस्मिन्नभेदेन भावनाया दुःखसम्भवात्। अतएवोक्तं -- श्रेयस्सृतिं भक्तिमुदस्य ते विभो क्लिशयन्ति ये केवलबोधलब्धये [भाग.10।14।14] इति। ते पुरुषोत्तमस्य भक्तिमुदस्य केवलस्याक्षरात्मनो बोधलब्ध्यै क्लिश्यन्तीति क्लेशोऽधिकःश्रम एव हि केवलं इत्याशयेन तरप् च। मद्भजनमार्गे त्वारम्भत एव परमानन्दः अक्षरज्ञानमार्गे त्वन्तत इत्यपि विशेषः।'),
('vallabhacharya-sc:source:12.6','Vallabhācārya','gita.12.6','sa','commentary','।।12.6।।एवमक्षरोपासकानां गतिमुक्त्वा स्वभक्तानामाह द्वाभ्याम् -- ये त्विति। तुशब्दः पूर्वेभ्यो भेदनिर्देशार्थः।,मयि स्वामिनि सेव्ये स्वस्य सर्वकर्माणि सन्न्यस्य लौकिकानि वैदिकानि च समर्प्य अनन्येनोक्तलक्षणैकभक्तियोगेन मां ध्यायन्त उपासते ध्यानार्चनसेवनप्रणामश्रुतिकीर्तनादीनि स्वयमेवात्यन्तप्रियाणि प्राप्य सरूपाणि कुर्वन्तो,मामुपासत इत्यर्थः। तेषां मत्प्राप्तिविरोधिमृत्युसंसारसागरादहमचिरेणैव समुद्धर्त्ताऽस्मि। अथवा मयि परमात्मनि नित्यप्रिये सति मन्निमित्तं वा लौकिकवैदिकानि सर्वाणि कर्माणि सन्त्यज्य बहिरन्तश्च त्यक्त्वा सद्व्रजप्रिया यच्छब्दवाच्यास्तु मत्पराः अनन्येनैव सर्वनिरपेक्षेणैव योगेन अनुवृत्तिमात्रसम्बन्धेनैव मां परमात्मप्रियं चिन्तयन्तो मत्समीप आसते।'),
('vallabhacharya-sc:source:12.7','Vallabhācārya','gita.12.7','sa','commentary','।।12.7।।तेषां तादृशानामहं तत्सन्बध्येवाहमित्यर्थःअहं भक्तपराधीनो ह्यस्वतन्त्र इव द्विज। वशे कुर्वन्ति मां भक्त्या सत्िस्त्रयः सत्पतिं यथा [भाग.9।4।63] इति वाक्यात्। न च तादृशानां कथं समुद्धारः सोपाधिभावनिदर्शनादिति वाच्यम् मन्निष्ठत्वेन निर्गुणत्वादित्याह -- मय्यावेशितचेतसामचिरेण समुद्धर्त्ता भवामीति मयि तथा भावकारणे वस्तुशक्तिरेवोद्धारिकान मय्यावेशितधियां कामः कामाय कल्पते इति वाक्यात्। न च तथात्वे तथाभूतानां सोपाधिकभक्तिमत्त्वं सगुणत्वापादकमिति शङ्क्यम् भगवद्रूपत्वेन तत्कामस्य निर्बीजत्वनिदर्शनात्। अतएवोक्तं भगवता -- केवलेन हि भावेन गोप्या गावो नगा मृगाः। येऽन्ये मूढधियो नागाः सिद्धा मामीयुरञ्जसा [भाग.11।12।8] इतिमन्निष्ठं निर्गुणं मतं इति च। अन्यथा सोपाधिकत्वेन विघातकत्वेन च कामस्य तत्र सत्त्वाद्भगवत्प्राप्तिर्नोक्ता स्यादित्युपरम्यते। इदं च विशेषतः श्रीमत्प्रभुचरणैः स्पष्टीकृतमेवेति ततोऽवसेयम्।'),
('vallabhacharya-sc:source:12.8','Vallabhācārya','gita.12.8','sa','commentary','।।12.8।।यस्मादेवं तस्मात् मय्येवेति। असाधारणवस्तुशक्त्याश्रये येन केन च सम्बन्धेन मनोनिवेशमात्रेण तन्निर्गुणत्वापादके प्रकटरूपे एव पुरुषोत्तमे परमात्मप्रिये मन आदिकं निवेशय सङ्कल्पविकल्पविषयकमपि मदीयमेव कुरु। व्यवसायोऽयमेव परं प्राप्यो नान्य इति बुद्धिर्धमस्तद्वृत्तीश्च मय्येव निवेशयैव। अत्रैवकारोऽन्यसर्वधर्मव्यावृत्त्यर्थकत्वाद्वक्ष्यमाणसर्वधर्मपरित्यागे बीजभूत उक्तः। अत ऊर्ध्वं एवम्भावानन्तरं मय्येव निवसिष्यसि? न त्वक्षरादौ धाम्नि? किन्तु मद्रूप इति भावः।'),
('vallabhacharya-sc:source:12.9','Vallabhācārya','gita.12.9','sa','commentary','।।12.9।।अथेति पक्षान्तरे। मुख्यकल्पासम्भवेऽनुकल्पमुपदिशति। चेन्मयि चित्तं स्थिरं समाधातुं न शक्तोऽसि अनिषिद्धो योगो न निष्पद्यते तर्हि अभ्यासयोगेन तत्स्थिरीकृत्य मामाप्तुमिच्छ।'),
('vallabhacharya-sc:source:12.10','Vallabhācārya','gita.12.10','sa','commentary','।।12.10।।यदि पुनः अभ्यासेऽप्यसङ्गसाधनेऽसमर्थोऽसि तर्हि पूजायां मत्सेवापरो भव? सेवापूर्वं मदर्थं कर्माणि कुरु।'),
('vallabhacharya-sc:source:12.11','Vallabhācārya','gita.12.11','sa','commentary','।।12.11।।अथैतदपि न कर्त्तुं त्वं शक्तोसि चेत्तर्हि मद्योगं मत्सम्बन्धसेव्यसेवकत्वरूपमाश्रितः सन् सर्वकर्मफलत्यागं कुरु। एतदुक्तं भवति -- ईश्वराज्ञया परमाचार्योपदिष्टशरणमार्गतः यथाशक्ति स्वधर्माचरणं फलादित्यागपूर्वकं सुखावहमिति मयि भारमारोप्य अन्यज्ञानयोगधर्मपरित्यागेन मदाश्रये कृतार्थतेति। विशेषस्त्वग्रे स्पष्टीकरिष्यते।'),
('vallabhacharya-sc:source:12.12','Vallabhācārya','gita.12.12','sa','commentary','।।12.12।।तमिमं फलादित्यागं स्तौति -- श्रेयो हीति। अभ्यासादुक्तपूर्वात् युक्तिसहितोपदेशपूर्वकं सर्वज्ञानं श्रेष्ठं? ततो ध्यानं निषेवणं? ततश्च फलत्यागः? ततोऽनन्तरं शान्तिः स्वास्थ्यमेव भवतीति विशिष्यते। शान्तिर्हि लाभेऽलाभे जये़ऽजये च मनस उपशमस्वरूपा? ततश्च कृतार्थतेत्यर्थसिद्धम्।'),
('vallabhacharya-sc:source:12.13','Vallabhācārya','gita.12.13','sa','commentary','।।12.13।।एवमादिधर्मवतो भक्तस्य द्वात्रिंशल्लक्षणं पुष्टिसूचकमिति तस्य स्वप्रियत्वमाह षड्गुणभगवतोऽनुग्रहात्प्रीतिविषयत्वाच्चैकेन षड्भिः श्लोकैः। यद्यपि भगवन्मार्गे सत्सङ्गादेर्भगवद्भक्तिहेतुत्वं तथापि तं प्रति भगवदनुग्रहस्यैव निर्हेतुकस्य हेतुत्वं सम्भवतिभवापवर्गो भ्रमतो यदा भवेज्जनस्य तर्ह्यच्युत सत्समागमः इत्यादि भागवते [10।51।54] भगवत्सेवकवाक्ये भवं अपवर्जयतीति तद्व्याख्यानादनुग्रह एव तत्र,हेतुरिति मूलभूततदनुग्रहीतत्वात्। अद्वेष्टेति।'),
('vallabhacharya-sc:source:12.14','Vallabhācārya','gita.12.14','sa','commentary','।।12.14।।सन्तुष्ट इति। यथालब्धेन भगवत्सेवोपयोगिना द्रव्येण देहधारणेन सन्तुष्टः। सततं योगी यतात्मा समवृत्तिः निरुद्धचेताः। दृढो भगवदेकसेवायां निश्चयो यस्य सोऽपि न बहिरेव तन्वादिना केवलम्? किन्तु मानसोऽभ्यन्तर इति। तदाह मय्यर्पितमनोबुद्धिरिति। श्रीपुरुषोत्तमेऽर्पिते मनोबुद्धी यस्य सद्बजौकसां यथा तथा स य एवम्भूतो द्विषड्गुणयुतो निर्हेतुकमद्भक्तिमान् स मे प्रियः। यो मद्भक्त इतीरणात्पुष्टिरस्तीति निश्चीयते। नहि भगवत्प्रियत्वं स्वकृति -- (स्वल्प) -- तपस्साध्यम्। अतः प्रवाहाद्भिन्नोऽयं मार्गः? प्रवाहस्य सर्वसाधारणत्वात् भक्तेर्निर्हेतुकानुग्रहैकलभ्यत्वान्महानेव भेदोऽस्तीति मन्तव्यं वेदमर्यादामार्गतोऽपि असङ्कीर्णत्वं चनाहं वेदैर्न तपसा [11।53] इति पूर्वमुक्तं सर्वतो (ऽत्र) वैदिककर्माद्यपेक्षयाऽस्योत्तमत्वकथनात् अभेदे तूत्कर्षवैयर्थ्यादिति सर्वं श्रीमदाचार्यग्रन्थादवसेयम्।'),
('vallabhacharya-sc:source:12.15','Vallabhācārya','gita.12.15','sa','commentary','।।12.15।।किञ्च यस्मादिति। भगवत्सेवाकर्मनिष्ठान्मैत्र्यात्तत्तदाचारसंशोधनप्रयोगात् लोको नोद्विजते। यश्च स्वयं तत्तदाचारपराङ्मुखात्तस्माल्लोकाच्च नोद्विजते? किन्तु स्वधर्मे एव निष्ठितो भवति तथा। स्वेष्टप्राप्तौ हर्षः? अप्राप्तौ वाऽमर्षः? कुतश्चिद्भयं प्रतिकूलादुद्वेगश्चिन्ता चेत्येभिर्मुक्तः प्रह्लाद इव स भक्तो मे प्रियः।'),
('vallabhacharya-sc:source:12.16','Vallabhācārya','gita.12.16','sa','commentary','।।12.16।।अनपेक्ष इति। मत्सेवातिरिक्तं सालोक्यादिकमपि नापेक्षते। तथासालोक्यसार्ष्टिसारूप्यसामीप्यैकत्वमप्युत। दीयमानं न गृह्णन्ति विना मत्सेवनं जनाः [3।29।13] इति भागवतवचनात्। शुचिराचारवान्आचारप्रभवो धर्मस्तेनैव च सुखी भवेत् इति वाक्यात्। तथा भगवत्सेवायां तत्तच्छृङ्गारयोजने दक्षः चतुरः। तत्प्रतिकूले गृहादावुदासीनः। तत्रापि गतव्यथःभार्यादीनां तथाऽन्येषामसतश्चाक्रमं सहेत् तथा कलत्रादिकं प्रतिकूलं दृष्ट्वा तदीयसर्वविषयारम्भपरित्यागी च। सेवायां हिउद्वेगः प्रतिबन्धो वा भोगो वा स्यात्तु बाधकः इति श्रीमदाचार्यैरप्युच्यते? अतः सर्वारम्भभोगोऽनुचितः घातकत्वात्। य एवम्भूतो भक्तः स मे प्रियः।'),
('vallabhacharya-sc:source:12.17','Vallabhācārya','gita.12.17','sa','commentary','।।12.17।।किञ्च यो न हृष्यति न द्वेष्टि च। परस्य दुःखं सुखं वा दृष्ट्वा प्राकृतवत् धनादिव्ययेऽपि न शोचति। न च तत्काङ्क्षति स्वभोगार्थंभगवानेव प्रभुः सर्वं विदधाति? निजेच्छातः करिष्यति इति भावेन न प्रार्थयते? चिन्तां वा न करोतीति। शुभाशुभपरित्यागी यः स भक्तिमान्मे प्रियः।'),
('vallabhacharya-sc:source:12.18','Vallabhācārya','gita.12.18','sa','commentary','Sri Vallabhacharya did not comment on this sloka'),
('vallabhacharya-sc:source:12.19','Vallabhācārya','gita.12.19','sa','commentary','।।12.19।।तुल्येति। स्वनिन्दास्तुती तुल्ये यस्य? न भगवत इति ()। तथा मौनी संयतवाक्। स्वयं च येनकेनचित् सन्तुष्टः? भगवति तु तेनैवोपभोगं साधयमानः। अनिकेत इतितादृशस्य गृहस्थानं विनाशकं इति सूचयति। एवं बाधराम्भावनयाऽनिकेतत्वमुक्तम्। तत्रापिबाधसम्भावनायां तु नैकान्ते वास इष्यते इत्याशयेनास्य विष्णोर्निकेतने प्रतिमायां मन्दिरे वा भगवदीयेषु तन्निवासेषु वा स्थिरा मतिर्यस्येत्येकं वा पदम्।'),
('vallabhacharya-sc:source:12.20','Vallabhācārya','gita.12.20','sa','commentary','।।12.20।।एवं मर्यादायामक्षरात्मनिष्ठात्स्वपुष्टिभक्तियोगनिष्ठस्यातीव प्रियत्वं प्रतिपादयन्नुक्तमुपसंहरति -- ये त्विति। ये दैवजीवा इदमेव सेवाधर्मादनपेतमुक्तममृतं यथावत्पर्युपासते निषेवन्ते श्रद्दधाना मदाश्रयास्ते भक्ता अतीव मे प्रिया इति। तथा भवेति भावः।अव्यक्तोपासनामार्गे दुःखं मर्यादयाऽपि हि। सुखं पुष्टया कृष्णभक्तिमार्गे सम्यगुदीरितम्।।1।।'),
('vallabhacharya-sc:source:13.2','Vallabhācārya','gita.13.1','sa','commentary','।।13.2।।सूत्रवत्पूर्वमुक्तस्य द्वितीयस्यापि वृत्तिवत्। तृतीयं सर्वनिर्णयं भाष्यमाभाष्यतेऽधुना।।1।।यत्तावत्प्रथममुपपादितं प्रकृतिद्वयं परापरविवेकेन परप्रकृतिस्वरूपं सोपस्करं क्षेत्रम्? अपरप्रकृतिस्वरूपं तु चेतनः क्षेत्रज्ञ इत्यक्षरमूलस्वरूपत्वात् ज्ञेयं तत्साधनभूतं ज्ञानं चोपदिशन् श्रीभगवानुवाच -- इदमिति। अन्यथा मध्ये प्रश्नं विना विवरणं नोपपद्येत। अत्र कैश्चिन्मूलेप्रकृतिं पुरुषं च [13।1] इति पद्यान्तरं लिख्यते तत्तूपेक्ष्यं? असम्भवेन सर्वाप्रयुक्तत्वात् पूर्वोक्तविवरणरूपत्वाच्चस्य षट्कस्य। तथाहि यथा पिण्डे तथा ब्रह्माण्डे इत्याशयात् या पूर्वं प्रकृतिरनात्मा इत्युक्ता तत्परिणामभूतमिदं शरीरं पुरुषस्य निवासभूतत्वाज्जीवनाद्वाक्षेत्रं इत्युच्यते तथाभूतमेतन्न विजानाति पुरुषो विविक्ततया तदा तु क्षेत्रित्वमात्र एव संसारी भवति। एतद्यो वा कश्चिद्विविक्ततया वेत्ति क्षेत्रं जानाति स्वं च द्रष्टारं तं तु क्षेत्रज्ञ इति तद्विदः प्राहुः।यद्यपि क्षेत्रक्षेत्रज्ञज्ञानं संसारदशायामप्यस्ति तथापि न विविक्ततया? किन्तु क्षेत्रसामानाधिकरण्येन तथापि तद्भोग्यं भोक्तुरात्मनोऽर्थान्तरभूतमेव मृतशरीरे तथा दर्शनात्। किञ्चोभयोः सम्बन्धे तु तत्सम्भवति? न कैवल्ये सम्भवति। यस्य वेत्तृत्वं तस्यैव वेद्यादन्यत्वमर्थसिद्धं दृष्टचरं घटादिनो द्रष्टुरिवदेवोऽहं इत्यतिमन्दानां नाहमितिवदात्मविशेषणतैकस्वभावतया तदपृथक्सिद्धेरुपपन्नं भवति। इदं तु पार्थक्यं स्वात्मानं क्षेत्रज्ञमेव भेदेन विजानतो विदुषो भवति? न सर्वस्येति।'),
('vallabhacharya-sc:source:13.3','Vallabhācārya','gita.13.2','sa','commentary','।।13.3।।यस्य च भवति स क्षेत्रज्ञ इह मत्स्वभावापन्न इत्याह -- क्षेत्रज्ञं चापि मां विद्धीति। नहि क्षेत्रिभावेन संसृष्टो जीवः क्षेत्रं स्वतो विविक्तं जानाति? यः कश्चिज्जानाति तं मां विद्धि मदंशत्वान्मद्रूपं पुरुषं जानीहि भगवद्गुणाविर्भावात्तद्गुणसारत्वात्तु तद्व्यपदेशः प्राज्ञवत् [ब्र.सू.2।3।29] इति सूत्रितत्वात्। आदरार्थमेतज्ज्ञानं स्तौतिक्षेत्रक्षेत्रज्ञयोर्ज्ञानं यत्तज्ज्ञानं मतं मम इति मदिच्छासम्मतं रक्षेत्।'),
('vallabhacharya-sc:source:13.4','Vallabhācārya','gita.13.3','sa','commentary','।।13.4।।एतत्प्रपञ्चयिष्यन् प्रतिजानीते -- तत्क्षेत्रमिति। यच्च यद्द्रव्यं? यादृक् येषामाश्रयभूतं? ये चात्र विकाराः सन्ति? यतश्चेति यदर्थमुद्भावितं? यत् यत्स्वभावं (स्वरूपं)। स च क्षेत्रज्ञो यः यत्स्वरूपः यत्प्रभावस्तत्सर्वं सङ्क्षेपेण मे मत्तः शृणु।'),
('vallabhacharya-sc:source:13.5','Vallabhācārya','gita.13.4','sa','commentary','।।13.5।।ऋषिभिर्बहुधा गीतमिति। क्षेत्त्रज्ञस्वरूपं बहुधा गीतं बहुप्रकारेण निरूपितस्य विप्रकीर्णस्यार्थस्यैकेन क्रोडीकारासम्भवादिति छन्दोभिर्ध्यानधारणाविषयत्वेन वैराजादिरूपेण नानायजनीयदेवतादिरूपेण क्षेत्रज्ञस्वरूपमुक्तं? तत्र विविधैरनेकैः पृथक् ब्रह्मसूत्रपदैश्च व्यासकृतैः वेदार्थसारग्रथनरूपैरतएव विनिश्चितैः हेतुमद्भिः हेतुः साधकवाक्यंतत्तु समन्वयात् [ब्र.सू.1।14] इतिवदनेकयुक्तिमद्भिरपि च बहुप्रकारेण गीतं मया तत्सर्वतः सारभूतं फलितं संगृह्योच्यते इति भावः।'),
('vallabhacharya-sc:source:13.6','Vallabhācārya','gita.13.5','sa','commentary','।।13.6।।महाभूतेति। तत् क्षेत्रं यद्द्रव्यं तन्महाभूतद्रव्यात्मकं स्थूलं यादृक्च अहङ्कारबुद्धिमहतामेकादशेन्द्रियविषयाणां लिङ्गशरीरसूक्ष्मभूतानां चाश्रयभूतम्।'),
('vallabhacharya-sc:source:13.7','Vallabhācārya','gita.13.6','sa','commentary','।।13.7।।तस्य यद्विकारितामाह -- इच्छेत्यादि। यद्यपीच्छाद्वेषसुखदुःखान्यात्मधर्मभूतानि तथाप्यात्मनश्चिदंशभूतस्य क्षेत्रसम्बन्धप्रयुक्तानीति क्षेत्राश्रितानीत्युच्यन्ते साङ्ख्ये पुरुषधर्मत्वं चपुरुषः सुखदुःखानां भोक्तृत्वे हेतुरुच्यते [13।21] इत्येव वक्ष्यते। सङ्घातः संहननं चेतनाविवेकाद्यात्मिका प्राणादिवृत्तिः धृतिश्चेति विकाराः। सुखदुःखे भुञ्जानस्य भोगापवर्गौ साधयतश्चिदंशभूतस्य वस्तुतोऽव्यक्तस्य पुरुषस्याधारतयोत्पन्नं भूतमयं शरीरं तेषामहङ्कारादीनामाश्रयं तत्तदिच्छासुखदुःखद्वेषसङ्घातादिविकारबहुलं विवेकधैर्यादिकचतुर्वर्गसाधकं मदिच्छयोद्भावितं स्वभक्त्यर्थं दिष्टकृतमन्यैः समुदङ्कितमिति मया तत् विनश्वरस्वभावं क्षेत्रं स्थूलं सूक्ष्मं च मानुषं शरीरं तुभ्यं समासेनोदाहृतम्।'),
('vallabhacharya-sc:source:13.8','Vallabhācārya','gita.13.7','sa','commentary','।।13.8।।अथ तस्मिन् क्षेत्रे स्वात्मज्ञानगुणानाह -- अमानित्वमिति सार्धैश्चतुर्भिः। एतेऽमानित्वादयो ज्ञानगुणा उक्ताः।'),
('vallabhacharya-sc:source:13.9','Vallabhācārya','gita.13.8','sa','commentary','।।13.9।।इन्द्रियार्थेष्विति -- विषयेषु।'),
('vallabhacharya-sc:source:13.10','Vallabhācārya','gita.13.9','sa','commentary','।।13.10।।असक्ितरिति अमुत्र भोगविरागः।'),
('vallabhacharya-sc:source:13.11','Vallabhācārya','gita.13.10','sa','commentary','।।13.11।।मयि चेति। अनन्ययोगेन अव्यभिचारिणी निर्हेतुकी भक्तिर्मध्ये हृदयरूपोक्ता।'),
('vallabhacharya-sc:source:13.12','Vallabhācārya','gita.13.11','sa','commentary','।।13.12।।एतत्प्रोक्तं ज्ञानं विद्याकार्यम्। यदतोऽन्यथा तदज्ञानमविद्याकार्यं प्रतिज्ञातम्।'),
('vallabhacharya-sc:source:13.13','Vallabhācārya','gita.13.12','sa','commentary','।।13.13।।ज्ञेयस्वरूपमाह षड्भिः स्वगुणरूपैः ज्ञेयमिति। शास्त्रतः ज्ञानिभिरधिगम्यम्। ज्ञानस्य फलमाह अमृतमिति। ज्ञेयं नामरूपलक्षणतो निर्दिशति -- अनादिमत्परं ब्रह्मेति। सर्ववेदान्तप्रतिपाद्यं यत्। यद्वा अहं परो यस्मात्तदक्षरं इति च। विरुद्धर्माश्रयं च तदित्याह -- न सत्तन्नासदिति। असत्त्वं सत्त्वं च विरुद्धौ धर्मौ तयोराश्रयंनहि विरोध उभयं भगवत्यपरिगणितगुणगण ईश्वरे इत्यादि भागवतवाक्यैरुच्यते।'),
('vallabhacharya-sc:source:13.14','Vallabhācārya','gita.13.13','sa','commentary','।।13.14।।तत्साकारं निराकारं वा इत्याशङ्क्याऽऽह -- सर्वतःपाणिपादान्तमिति। साकारमेव सर्वत्र प्रदेशे पाणयः पादा अन्ता यस्य। गतिकृतिलक्षणे क्रिये सर्वत्र अन्तपदेन स्वेच्छया परिच्छेदावभानं चोक्तम्। सर्वतोऽक्षिशिरोमुखं इति ज्ञानप्राधान्यभोगाश्च सर्वत्र चोक्ताः। नामप्रपञ्चार्थमाह -- सर्वत्र श्रुतिमल्लोक इति। सर्वतः शृणोतीत्यर्थः। एतादृशस्य परिच्छेदः सम्भविष्यतीत्याह -- सर्वमावृत्य तिष्ठतीति। एते धर्माः प्रपञ्चोत्पत्त्यनन्तरमेव स्पष्टा भवन्ति? तथापि तेषां नित्यत्वख्यापनाय प्रथमतो वचनम्।'),
('vallabhacharya-sc:source:13.15','Vallabhācārya','gita.13.14','sa','commentary','।।13.15।।सर्वत्र परिच्छेदस्य प्रयोजनं तूपपादितमेवअनन्तं [11।47]अव्यक्तं [13।6] इत्यत्र। एतेन सर्वतश्चक्षुरादिकार्यकृत्त्वमुक्तं अपाणिपादो जवनो ग्रहीता पश्यत्यचक्षुः स शृणोत्यकर्णः [श्वे.3।19ना.प.उ.9।14] विश्वतश्चक्षुरुत विश्वतोमुखः [ऋक्सं.4।7।27।1म.ना.2।2श्वे.उ.3।3] इति प्राकृतनिषेधपूर्वकमप्राकृतश्रवणात्। विरुद्धर्माश्रयत्वमाह -- सर्वेन्द्रियगुणाभासमिति।'),
('vallabhacharya-sc:source:13.16','Vallabhācārya','gita.13.15','sa','commentary','।।13.16।।तस्यैव प्रपञ्चात्मकतामाह -- अचरं चरमेव चेति।द्विरूपं तद्धि सर्वं स्यादेकं तस्माद्विलक्षणम् इति। अचरं जडं तत्। सदेव सोम्येदमग्र आसीत् [छां.उ.6।2।1] इति सर्वं खल्विदं ब्रह्म [छा.उ.3।14।1] इत्यादिश्रुतेः। चरं जङ्गमं जीवरूपं च तत्त्वमसि श्वेतकेतो [छां.उ.6.816] इति श्रुतेः सूक्ष्मत्वादविज्ञेयं तत् दूरस्थमन्तिके च तत्। तथा च मन्त्रः तदेजति तन्नैजति तद्दूरे तद्व(द)न्तिके। तदन्तर(म)स्य सर्वस्य तदु सर्वस्य बाह्यं (बाह्यतः) [ईशो.5] इति।'),
('vallabhacharya-sc:source:13.17','Vallabhācārya','gita.13.16','sa','commentary','।।13.17।।तर्हि खण्डशः स्यादित्याशङ्क्याऽऽह -- अविभक्तमिति। अनन्तमूर्तिष्वपि न परस्परं विभेदः? केवलमिच्छया तावन्मात्रप्रकटनार्थं विभक्तमिव च स्थितम्। पालकरूपेण भूतभर्तृ? संहारकरूपेण ग्रसिष्णु? प्रजापतिरूपेण प्रभविष्णु च। यथोक्तं निबन्धे -- अनन्तमूर्ति तद्ब्रह्म (स्व) ह्मविभक्तं विभक्तिमत्। बहु स्यां प्रजायेयेति वीक्षा तस्य ह्यभूत्सती। तदिच्छामात्रतः सृष्टा ब्रह्मभूतांशचेतनाः। सृष्ट्यादौ निर्गताः सर्वे निराकारास्तदिच्छया।।विस्फुलिङ्गा इवाग्नेस्तु सदंशेन जडा अपि। आनन्दांशस्वरूपेण सर्वान्तर्यामिरूपिणः।।इत्यादि। अस्यार्थः -- बहु स्यामिति अनेकत्वमुच्चनीचत्वं भावयामास। भावना तस्य विषयाव्यभिचारिणी। तदिच्छामात्रतः सृष्टा ब्रह्मभूताः? न तु योगबलेनाविर्भूताः अंशाः मन्दप्रकाशाः साकाराः सूक्ष्मपरिच्छेदाः? चेतनाश्चित्प्रधानाः। सर्वेऽसङ्ख्याताः प्रथमसृष्टौ। ततः साकारा भगवद्रूपा अपि उच्चनीचभावेच्छया निर्गता इति निराकारा जाताः? विस्फुलिङ्गा इव वह्नेः। प्रकृतिः तद्गुणाश्च सत्प्राधान्येन,अन्तर्यामिणस्तु आनन्दांशस्वरूपेण। यथा जीवानां नानात्वं तथाऽन्तर्यामिणामपि? एकस्मिन् हृदि हंसरूपेणोभयोः प्रवेशात्। अतएवात्रापिसर्वस्य हृदि धिष्ठितं इत्युक्तम्। भेदस्तु जीवेऽपि नास्तीति न काप्यनुपपत्ति? इत्येवं त्रैविध्यमंशेन? तत्रापि विचारः -- सति चिदानन्दधर्मयोस्तिरोभावः? चित्यानन्दस्य आनन्दांशतिरोभावस्यापि ज्ञापकं तु निराकारा इति। भगवदाकारश्चतुर्भुजाद्यानन्दमयाकार आकारशब्देनोच्यते आनन्दस्यैव भगवत्याकारसमर्पकत्वात्। एवं स्वरूपेऽवैजात्यं? नामतो वैजात्यं जडश्चिदन्तर्यामिण इति व्यवहार इति।'),
('vallabhacharya-sc:source:13.18','Vallabhācārya','gita.13.17','sa','commentary','।।13.18।।ज्योतिषामिति। प्रकाशकानां चेतनानां च तन्मूलं ज्योतिरध्यात्मरूपं प्रकाशकं। अतएवोक्तं -- चैत्त्यस्य तत्त्वममलं मणिमस्य कण्ठे [भाग.3।38।28] इति। तमसः प्रकृतेः परं तम आसीत्तमसा गूह्ळमग्रे प्रकेतं [ऋक्सं.8।7।17।3] इति श्रुतावप्युच्यते। अन्तर्यामिपदं च तदित्याह -- हृदि सर्वस्य धिष्ठितमिति स्पष्टम्। ज्ञायतेऽनेनेति ज्ञानं चैतन्यं ज्ञानसाधनं अमानित्वादिरूपं वा। तत्तु ज्ञेयं च तज्ज्ञानगम्य हृदि सर्वस्य धिष्ठितम्।'),
('vallabhacharya-sc:source:13.19','Vallabhācārya','gita.13.18','sa','commentary','।।13.19।।प्रकृतिः पुरुषश्चोभौ परमात्माऽभवत्पुरा। यद्रूपं समधिष्ठाय तदक्षरमुदीरितम् इतीति।महाभूतान्यहङ्कारः इत्यादिनासङ्घातश्चेतना धृतिः [13।67] इत्यन्तेन क्षेत्रतत्वं समासेनोक्तं?अमानित्वं [13।812] इत्यादिनातत्वज्ञानार्थदर्शनम् इत्यन्तेन ज्ञानं?ज्ञेयम् [13।18] इत्यादिना ज्ञेयं तत्तदप्यात्मतत्त्वस्य ज्ञानसाधनमुक्तं?अनादिमत्परं [13।13] इत्यादिना चहृदि सर्वस्य धिष्ठितं [13।18] इत्यन्तेन ज्ञेयस्य च ब्रह्मणोऽक्षरात्मत्वं सङ्क्षेपेणोक्तम्। इदं सर्वं मद्भक्तिमानेव विज्ञाय मद्भावाय मद्गुणवत्वायोपपन्नो भवतीत्यर्थः।');
--> statement-breakpoint
INSERT INTO commentary_fts (unit_id,author,canonical_ref,language,content_type,content) VALUES
('vallabhacharya-sc:source:13.20','Vallabhācārya','gita.13.19','sa','commentary','।।13.20।।अथस च यो यत्प्रभावश्च [13।4] इत्येतत्पूर्वप्रतिज्ञातं पुरुषतत्त्वं कथयिष्यन् अत्यन्तविभक्तस्वभावयोः प्रकृत्यात्मनोः कारणस्वरूपादनन्ययोः सफलं सर्वहेतुत्वमाह -- पञ्चभिः। तत्र प्रकृतिरात्मव्यतिरिक्ता साङ्ख्यैकदेशिनो मते पुरुषवन्नित्या। भगवदीयसाङ्ख्ये तु भागवतः शक्तिः। साङ्ख्यशास्त्रं तु न भगवन्तं विषयीकरोति तत्प्रवर्त्तकत्वात्तन्नियामकत्वाच्च। अक्षरादर्वागेव तच्छास्त्रप्रवृत्तेः पञ्चधा भावना अनादिः पुरुषोत्तमोऽक्षरं कालः प्रकृतिपुरुषाविति। इदं मतमाश्रित्यात्र साङ्ख्यसिद्धान्तप्रवृत्तिः? न तु प्राकृतमाश्रित्य।तथाहि -- प्रकृतिमिति। पुरुषमिति। उभयत्र सर्वसमष्टिरूपविवक्षयैकवचनम्। एतच्चस एव (एषः) प्रकृतिं सूक्ष्मां दैवीं गुणमयीं विभुः। यदृच्छयैवोपगतामभ्यपपद्यत लीलया। गुणैर्विचित्राः सृजतीं सरूपाः प्रकृतिं प्रजाः। विलोक्य सद्यो मुमुहे स इह ज्ञानगृहया [भाग.3।26।4?5] इति भागवतवाक्येनैकार्थयति। तत्र कार्यकारणरूपेण प्रकृतिर्द्विविधा? कार्यरूपा जीवात्मोपाधिरविद्यायुक्ता कारणरूपा माया परमात्मनः। एवं पुरुषोऽपि द्विविधः कारणमंशी मूलपुरुषात्मा? तस्य कार्यं अंशा जीवपुरुषा इति। तत्र स एव पुरुषः प्रकृतिं लीलया क्रीडया हेतुनाऽभ्यपद्यत। कीदृशीं प्रकृतिं यदृच्छयैव भगवदिच्छयैवोपगतामिति। तां तं च उभावप्येतौ चिरादधिगम्यमानौ मदंशभूतौ सच्चित्स्वभावौ कारणस्वरूपानन्यत्वादनादी एव विद्धि। बन्धहेतुभूतान्विकारांश्चेच्छाद्वेषादीन् अमानित्वाद्विकारांश्च। गुणानमृतहेतुभूतान्सत्वादीन्वा प्रकृतिसम्भवाननादीन् विद्धि। सर्गकाले मे मायांशागुणात्मिकाऽचेतना प्रकृतिः पुरुषेण मूलभूताक्षरांशेन संसृष्टा महदहङ्कारभूम्यादिरूपिणी क्षेत्राकारेण विपरिणता अन्तरासृष्ट्या नीहाररूपयाऽविद्ययाऽध्यस्ता प्रकृतिः सविकारैरिच्छाद्वेषादिभिः पुरुषस्य बन्धहेतुः। सैव मायानिर्मितया विद्ययाऽवगताऽमानित्वादिभिः स्वविकारैः पुरुषस्यामृतहेतुर्भवतीत्यर्थः।'),
('vallabhacharya-sc:source:13.21','Vallabhācārya','gita.13.20','sa','commentary','।।13.21।।सृष्ट्यां तयोः कार्यभेदमाह -- कार्येति। कार्यं बन्धमोक्षरूपं? तस्य कारणरूपा विकारा गुणाश्च एतेषां कर्त्तृत्वे समुत्पादकत्वे पुरुषाधिष्ठिता प्रकृतिर्हेतुः?प्रकृतिसम्भवान् [13।20] इत्युक्तत्वात्। पुरुषस्य तु तदन्तश्चेतयितृत्वमेव तदपेक्षयाऽधिकंकर्त्ता शास्त्रार्थवत्वात् [ब्र.सू.2।3।33] इत्यादिसूत्रोक्तं क्षेत्राधिष्ठानप्रयत्नहेतुत्त्वमेव पुरुषस्य कर्तृत्वं प्राकृतवदभ्युपगम्यते। स तु तत्संसृष्टस्तदुद्भूतानां सुखदुःखानां,भोक्तृत्वे हेतुः सुखदुःखाद्यनुभवाश्रयः। यद्यप्युभयं क्षेत्रधर्म इति वक्तव्यं तथापि विक्रियाया जडावसानत्वात् क्षेत्रप्राधान्यं भोगस्य चिदवसानत्वदर्शनाच्चेतनाप्राधान्यमित्यर्थः।'),
('vallabhacharya-sc:source:13.22','Vallabhācārya','gita.13.21','sa','commentary','।।13.22।।एवं कार्यभेदमुक्त्वा तद्भोक्तृत्वमपि तस्य प्रकृतिपरिणामक्षेत्रसंसर्गेणैव भवति? नान्यथेत्याह -- पुरुष इति। प्रकृतिस्थ एव क्षेत्रस्थ एव जीवः प्रकृतिजान् गुणान् सत्त्वादिपरिणामभूतांस्तत्कार्यभूतैरिन्द्रियैर्भुङ्क्ते भोक्ता भवति? न त्वन्तर्यामिवदसङ्गः अनश्नन्नन्यो अभिचाकशीति [ऋक्सं.2।3।17।5मुं.उ.3।1।1श्वे.उ.4।6] यथोक्तं भागवते -- [3।26।67]एवं पराभिध्यानेन कर्तृत्वं प्रकृतेः पुमान्। कर्मसु क्रियमाणेषु गुणैरात्मनि मन्यते।।तदस्य संसृतिर्बन्धः पारतन्त्र्यं च तत्कृतम्। भवत्यकर्तुरीशस्य साक्षिणो निर्वृतात्मनः इतिकार्यकारणकर्त्तृत्वे द्रव्यज्ञानक्रियाश्रयाः। बध्नन्ति नित्यदा मुक्तं मायिनं पुरुषं गुणाः [2।5।19] इति च। अतोऽस्य पुरुषस्य प्रकृतिसंसर्गेण तिरोहिताक्षरस्वभावस्य तद्गुणसङ्ग एव सदसद्योनिजन्मसु कारणं ज्ञातव्यम्।'),
('vallabhacharya-sc:source:13.23','Vallabhācārya','gita.13.22','sa','commentary','।।13.23।।किञ्च -- उपद्रष्टेति। अस्मिन्वृक्षरूपके देहे द्वा सुपर्णा सयुजा सखाया समानं वृक्षं परिषस्वजाते। तयोरेकः पिप्पलं स्वाद्वत्ति? अनश्नन्नन्यो अभिचाकशीति [ऋक्सं.2।3।17।5मुं.उ.3।1।1श्वे.उ.4।6] इति मन्त्रैकवाक्यार्थतया भगवताऽन्योऽपि परमात्माऽन्तर्यामिपुरुष उच्यतेऽसङ्गः प्रसङ्गादिति गम्यते। अतएवपरमात्मा इति चेति पदं दीयतेपरः पुरुषः इति च। सोऽप्युक्त उपद्रष्टा साक्षी वस्तुतः कार्यकारणभोगसङ्गानपेक्षः स्वत एव मुख्यभोक्ता कर्ताषाड्वर्गिकं जिघ्रति षड्गुणेशः इति वाक्यात्। अविज्ञातोऽनुमन्ता च महेश्वरो नियन्ता प्रेरकश्च यद्यपि देहेऽस्मिन् वर्त्तते? तथापि स निर्लेपः अनशनात्। अयं प्राणभृत्तु लिप्तोऽशनादित्येवम्भूतं पुरुषं देहेऽस्मिन्वर्त्तमानं उभयविधं वस्तुतोऽक्षरप्रभावं क्षेत्रज्ञं ब्रह्मांशभूतं चेतनं पुरुषं हंसस्वरूपभूतं स्वरूपतो विविक्तं निर्गुणं च यो वेत्ति प्रकृतिं च गुणैः सह वर्त्तमानां यो वेत्ति? स गुणैर्वर्त्तमानो वा भूयः सर्वथा नाभिजायते न गुणप्रवाहसंसारं भजते किन्तु मुच्यत इत्यर्थः।'),
('vallabhacharya-sc:source:13.24','Vallabhācārya','gita.13.23','sa','commentary','।।13.24।।Sri Vallabhacharya did not comment on this sloka.'),
('vallabhacharya-sc:source:13.25','Vallabhācārya','gita.13.24','sa','commentary','।।13.25।।एवम्भूतदर्शनसाधनविकल्पानाह -- द्वाभ्यां ध्यानेनेति। आत्मनि स्वस्मिन् आत्मना स्वेन? अन्ये साङ्ख्येन योगेनाष्टाङ्गेन? कर्मयोगेन चापरे निष्कामेन पश्यन्त्यात्मानम्।'),
('vallabhacharya-sc:source:13.26','Vallabhācārya','gita.13.25','sa','commentary','।।13.26।।अन्ये त्विति। अतिमन्दाधिकारिणोऽन्येभ्यस्तत्त्वदर्शिभ्यो ज्ञानिभ्यः श्रुत्वाकर्मणा [3।20] इत्यादिभिरात्मानमुपासते? ततस्तेऽप्यात्मदर्शनेन मृत्युं संसारमतितरन्ति? ये श्रुतिपरायणास्त एव। अपिचशब्दोपादानात्पूर्वभेदोऽवगम्यते।'),
('vallabhacharya-sc:source:13.27','Vallabhācārya','gita.13.26','sa','commentary','।।13.27।।अथ साङ्ख्यरीत्या प्रकृतिसंसृष्टस्यात्मनो विवेकानुसन्धानप्रकारं वक्तुं स्थावरजङ्गमं च सत्त्वं सच्चित्संसर्गजमित्याह -- यावदिति। सत्त्वं भूतमात्रं स्थावरं जङ्गमं च जायते तत् क्षेत्रक्षेत्रज्ञयोः सम्बन्धात्उभययुजा भवन्त्यसुभृतो जलबुद्बुदवत् [भाग.10।87।31] इति वाक्यात्। क्षेत्रात्मनोरन्योन्यसंयोगादिह जायते संयुक्तावेव? नेतरेतरवियुक्तावित्यर्थः।'),
('vallabhacharya-sc:source:13.28','Vallabhācārya','gita.13.27','sa','commentary','।।13.28।।अथ पुनरपि सुग्रहणायात्मदर्शनमाह -- तत्रात्मा त्रिविधोऽन्तर्यामी पुरुषोऽव्यक्तश्च। तत्र प्रथमस्य दर्शने फलमाह -- द्वाभ्यां सममिति। तत्र यः समं तिष्ठन्तं सर्वभूतेषु परमात्मानमन्तर्यामिणमीश्वरं पश्यति स सम्यग्दर्शनः? विनश्यदवस्थेषु सत्प्रकृतिकार्यशरीरेषु जातिवदविनश्यन्तं ज्ञातृत्वेन समानाकारं यः पश्यति स पश्यति।'),
('vallabhacharya-sc:source:13.29','Vallabhācārya','gita.13.28','sa','commentary','।।13.29।।समं पश्यन् आत्मना आत्मानं न हिनस्ति नान्यथा प्रतिपद्यते? किन्तु याथातथ्येनावैति हीति युक्तंयोऽन्यथा सन्तमात्मानमन्यथा प्रतिपद्यते। किं तेन न कृतं पापं चौरेणात्मापहारिणा [म.भा.1।74।27] इति श्रुतिप्रामाण्यात्। अपितु संरक्षति संसारमत्येति अतिमृत्युमेति [यजुस्सं.31।18श्वे.उ.3।8।6।15] इति,श्रुतिप्रतिपादितार्थः? ततो ज्ञातृतया सर्वत्र समानाकारदर्शनात् परां गतिं सच्चिदानन्दकां भगवद्धामरूपामक्षरात्मिकां याति।'),
('vallabhacharya-sc:source:13.30','Vallabhācārya','gita.13.29','sa','commentary','।।13.30।।द्वितीयस्यापि स्वस्य दर्शने फलमाह -- प्रकृत्यैवेति। साङ्ख्ये तु प्रकृत्यैव क्रियमाणानि कर्माणि कर्तृत्वं चेष्टावत्त्वेन प्रकृत्याश्रयं? न तु केवल आत्मनि जीवस्वरूपेऽणुपरिमाणमात्रे चिद्रूपेऽपि मुख्यकर्तृपुरुषोत्तमांशभावानुसन्तत्यैव देहद्वयोपाधिवैशिष्टये तु तत्र कर्तृत्वं प्राकृतमेवेति ध्येयं? तथा चैवमन्ततोऽकर्त्तारमात्मानं स्वस्वरूपं निरुपाधिभावं पश्यति स पश्यति अन्ये त्वन्धाः।'),
('vallabhacharya-sc:source:13.31','Vallabhācārya','gita.13.30','sa','commentary','।।13.31।।तृतीयेऽपि फलं दर्शयति -- यदेति। प्रकृतिपुरुषतत्त्वात्मकेषु देवादिभूतेषु सत्सु तेषां देवत्वमनुष्यत्वादिदीर्घह्रस्वस्थूलकृशत्वादिकं पृथग्भावं पृथक्त्वेन वा ज्ञायमानं उभयस्वरूपमेकस्थं प्रकृतिस्थं समष्टिपुरुषस्यं च पश्यति? तत एव च निर्गमनविस्तारं यथाऽग्नेः क्षुद्रा विस्फुलिंङगा ৷৷. एवमेवास्मादात्मनः ৷৷. भूतानि व्युच्चरन्ति [बृ.उ.2।1।20] इत्यादि श्रूयमाणं साक्षात्करोति तदा ब्रह्माक्षरं सम्पद्यते अनवच्छिन्नाक्षरात्मैक्यं प्राप्नोति। अयमर्थः -- क्षुद्रप्रवाहवद्व्यष्टिः समष्टिर्गाङ्गनीरवत्। अक्षरं तच्छक्तिवद्धि देवतावत्परो हरिः।।अक्षरेण सहैक्यं हि पुरुषस्याह तच्छ्रुतिः। पुरुषोत्तमतस्त्वैक्यं प्रवेशः स्वेच्छया मतः।।[व.सि.मु.] एतद्विषये मिथ्यावादिभिराविद्यको भेदः कल्पयित्वोपदिश्यते दृग्दृश्यव्यवहारमभ्युपगम्येति तदुपेक्ष्यं श्रौतानां श्रौत एव व्यवहारः? न यौक्तिकः? इत्यभियुक्तोक्तेः? विशेषस्तु निबन्धादवगन्तव्यः।'),
('vallabhacharya-sc:source:13.32','Vallabhācārya','gita.13.31','sa','commentary','।।13.32।।स्वतः पुरुषस्य प्राकृतसम्बन्धाभाव इत्युपपादयति -- अनादित्वादिति। परमात्माऽन्तःपुरुषः अथवा अक्षररूपत्वेन अनादित्वान्निर्गुणत्वादयं आत्मा जीवः पुरुषोऽव्ययः केवलं भगवदिच्छया स्वतः पृथग्भावितोऽप्यकर्त्ताऽलिप्तः अध्यासेनैव तथा? नान्यथेति भावः।'),
('vallabhacharya-sc:source:13.33','Vallabhācārya','gita.13.32','sa','commentary','।।13.33।।यद्यपि निर्गुणत्वान्न करोति तथापि नित्यसंयुक्तैर्देहस्वभावैः कथं न लिप्यते इत्यत्राह दृष्टान्तेन -- यथा सर्वगतमिति। आकाशवत्सर्वाश्रयव्यापी सौक्ष्म्यादणुत्वाद्धेतोः जीवः आत्माऽपि तथा नोपलिप्यते सर्वाश्रयव्यापित्वं तु व्यापिचैतन्यगुणादेव युज्यते चन्दनादिवदिति।'),
('vallabhacharya-sc:source:13.34','Vallabhācārya','gita.13.33','sa','commentary','।।13.34।।प्रकाशकत्वं च दृष्टान्तान्तरेण स्पष्टयति -- यथेति। चैतन्यं ज्ञानरूपमात्मनो धर्मः न प्राकृत इति। यथा सूर्यः प्रकाशधर्मवान् सर्वं प्रकाशयति तथाऽयं क्षेत्रीति। अनेन पुरुषस्य क्षेत्रित्वमेव? साम्प्रतं तत्त्वज्ञानेन भगवद्गुणसारत्वात्तद्व्यपदेशः क्षेत्रज्ञत्वं भवतीति बोधितम्।'),
('vallabhacharya-sc:source:13.35','Vallabhācārya','gita.13.34','sa','commentary','।।13.35।।उक्तमुपसंहरति -- क्षेत्रेति। उक्तप्रकारेण अन्तरं भेदं विवेकं तत्त्वज्ञानदृष्ट्या भूतप्रकृतेर्मोक्षो यस्मात्तमुपायं अमानित्वादिकं च ये विदुस्ते परं तत्त्वज्ञानं पुरुषोत्तमप्रापकं प्राप्नुवन्ति।'),
('vallabhacharya-sc:source:14.1','Vallabhācārya','gita.14.1','sa','commentary','।।14.1।।अनादित्वान्निर्गुणत्वात्पुरुषो विमलः स्वतः। अनादित्वेऽपि मलिना प्रकृतिस्त्रिगुणा यतः।।1।।तत्सम्बद्धप्रपञ्चेऽस्मिन् गुणातीतस्तु कश्चन। इत्युच्यतेऽस्मिन्नध्याये गुणत्रयविभागशः।।2।।तत्र पूर्वंयावत्सञ्जायते किञ्चित् [13।27] इत्युक्तं स च क्षेत्रात्मनोः संयोगो निरीश्वरसाङ्ख्यानामिव? न स्वातन्त्र्येण किन्तु भगवदिच्छयेति कथनपूर्वकंकारणंक गुणसङ्गोऽस्य [13।22] इत्यनेनोक्तं सत्त्वादिगुणकृतं जगद्वैचित्र्यं प्रपञ्चयिष्यन्क्षेत्रक्षेत्रज्ञयोरेवमन्तरं ज्ञानचक्षुषा। भूतप्रकृतिमोक्षं च ये विदुर्यान्ति ते परम् [13।35] इति परशब्दं च विवृण्वन् श्रीभगवानुवाच -- परं भूय इति द्वाभ्याम्। पूर्वश्लोकोक्तं यत्परं तद्भूयः प्रवक्ष्यामि विवृण्वन्वक्ष्यामीति प्रशब्दार्थः। किं तत्परं ज्ञानानामुत्तमं ज्ञानमिति ज्ञायते इति ज्ञानं अचिन्त्यशक्तिमहिमपुरुषोत्तमविषयकं तत्त्वज्ञानं यदधिगम्य मुनयः परां गुणातीतां मुक्तिं गताः? इतस्त्रैगुण्यात्।'),
('vallabhacharya-sc:source:14.2','Vallabhācārya','gita.14.2','sa','commentary','।।14.2।।इदं वक्ष्यमाणं मम साधर्म्यं षड्गुणवत्तया साम्यं प्राप्ता एके ते सर्गेऽपि नोपजायन्ते? प्रलये च न व्यथन्ति किन्तु नित्यं समीपे तिष्ठन्तीत्यर्थः। अनेन मुक्तानां तत्र बाहुल्यं सूचितंअनुव्रता यत्र हरेः इत्यादिवाक्यात्।'),
('vallabhacharya-sc:source:14.3','Vallabhācārya','gita.14.3','sa','commentary','।।14.3।।तदेवं प्रशंसया श्रोतारमभिमुखीकृत्य स्वस्याचिन्त्यशक्तिवैभवलीलां दर्शयति -- ममेति। तत्रसर्गेऽपि नोपजायन्ते [14।2] इत्यत्राभिप्रेतं सर्गस्य प्राकृतत्वेन सगुणत्वं वदन् तत्सम्भवमाह -- मम योनिरिति। गुणानां हेतुभूता सर्वस्य भूतजातस्य मत्प्रकृतिगुणसंसर्गजत्वं पूर्वोक्तं मयैव कृतमिति स्पष्टयितुं ममेति। मम सदंशभूता योनिः निषेकस्थानं प्रकृतिः त(तस्मा)देतद्ब्रह्म नामरूपमन्नं च जायते [मुं.उ.1।1।9] इति श्रुतेर्ब्रह्मांशभूतत्वान्महद्ब्रह्मेत्युच्यते सूत्रभूतादिकारणभूताऽचेतना? तत्र गर्भं बीजभूतं सूत्रं चेतनपुञ्जीभूतं च दधाम्यहमक्षरात्मा पुरुषः स धारणमीक्षणद्वारा भवति तदेव बीजमित्युच्यते तत्सम्मृष्टपुरुषो विराट्? तत्संसृष्टा उभयस्वरूपाश्चेतना अणवो व्युञ्चरिता जायायामिवात्मा वै जायते इति तदंशभूता मत्स्वरूपचैतन्यतोऽभिन्नाः प्राणधारणप्रयत्नवन्तोऽनेके जीवा इति व्यपदिश्यन्ते। तदाह -- तत इति। गर्भात्सर्वभूतानां सम्भवो भवति।'),
('vallabhacharya-sc:source:14.4','Vallabhācārya','gita.14.4','sa','commentary','।।14.4।।एवं कार्यावस्थोऽयं चिदचित्प्रकृतिसर्गो मयैव कृत इति सर्वयोनिष्विति। नेदमपूर्वतरमिवोच्यते किन्तु सर्वत्रैवमेव लोके दृश्यत इत्याह एकः पिताऽन्यत्क्षेत्रमिति। तत्र तासां भूतमूर्तीनां महद्ब्रह्म योनिः? अहं बीजप्रदः पितेति वस्तुतोऽवसेयम्। अत एव विष्णुपुराणादौ लक्ष्मीनारायणौ गौरीशङ्करौ सर्वत्र स्त्रीपुम्भावापन्नस्वरूपौ निरूपितौ।'),
('vallabhacharya-sc:source:14.5','Vallabhācārya','gita.14.5','sa','commentary','।।14.5।।अनेन स्वस्येच्छया जीवेषु निजप्रकृतिसम्भवसंसर्जनलीलामुपपाद्येदानीं बन्धलीलामुपपादयितुं चतुर्दशलोकबन्धहेतुभूतगुणानाह चतुर्दशभिः -- सत्त्वमिति। नचैते सकार्या आत्मनो गुणाः? अपितु प्रकृतेरुक्ताः प्रकृतिसम्भवा इति सम्भूतं चेतनं तत्तद्देहे गुणा एव बध्नन्ति। प्रकृतिधर्म एव तत्र हीनतापादको देहे अहंवृत्तिमान् नोपाधिविशिष्टस्य नान्यस्य। ये च भगवदंशभूतायां प्रकृतौ समागता गुणास्ते भगवतः सच्चिदानन्दा एव मूलतः परिणममाना बन्धका दोषा जडगतत्वात्। बन्धनश्लेषात्गुणाः इति संज्ञा तेषाम्। तदेवाह निबध्नन्तीति। तत्र प्रकृतिरुद्भूता गुणाः सत्त्वादयो देहाभिमानिनस्तमणुस्वरूपं चिदंशं जीवमव्ययमपि निबध्नन्ति। त्वं तं बन्धं,निवर्त्तयेति सम्बोधयति।'),
('vallabhacharya-sc:source:14.6','Vallabhācārya','gita.14.6','sa','commentary','।।14.6।।तत्र क्रमतो लक्षणं गुणानां बन्धनप्रकारं च वदन् पूर्वं सत्त्वस्य तदाह -- तत्रेति। सत्त्वं प्राकृतत्वात् सुखसङ्गेन ज्ञानसङ्गेन च लौकिकेन बध्नाति? पुरुषस्य सुखे ज्ञाने च सङ्गं जनयतीत्यर्थः। ज्ञानसुखयोः सङ्गे जाते तत्साधनेषु लौकिकवैदिकेषु पुरुषप्रवृत्तिः? ततश्च तत्फलानुभवसाधनभूतासु योनिषु जायते इति सत्त्वं मर्यादया तद्द्वारेण पुरुषं बध्नाति। एवमेवान्यत्र। लक्षणं तु निर्मलत्वादिति मूले उक्तमेव? एवमन्ययोरपि लक्षणं स्पष्टमेव मूले। तथा च सत्त्वं प्राकृतं सोऽहं सुखी शब्दादिज्ञानी चेति ज्ञानसुखसङ्गजनेन () बन्धकमित्युक्तं भवति।'),
('vallabhacharya-sc:source:14.7','Vallabhācārya','gita.14.7','sa','commentary','।।14.7।।रजसोऽप्याह -- रज इति। अनुरागात्मकंरञ्ज रागे इति धातोः स्पष्टमेव। कर्मसु,रञ्जनाद्बन्धकम्।'),
('vallabhacharya-sc:source:14.8','Vallabhācārya','gita.14.8','sa','commentary','।।14.8।।तमसश्चाह -- तम इति। विरुद्धज्ञानजन्यं? अविद्याजन्यमिति वा।'),
('vallabhacharya-sc:source:14.9','Vallabhācārya','gita.14.9','sa','commentary','।।14.9।।सत्त्वादाना स्वभावमाह -- सत्त्वमिति। सुखादिसञ्जनस्वभावमित्यर्थः। एवमन्यदपि ज्ञेयं तत्र हेतुमाह -- ज्ञानमिति।'),
('vallabhacharya-sc:source:14.10','Vallabhācārya','gita.14.10','sa','commentary','।।14.10।।रजस्तमश्चेति। गुणद्वयमभिभूय सत्त्वं भवत्यदृष्चवशात्। एवमन्यदपि।'),
('vallabhacharya-sc:source:14.11','Vallabhācārya','gita.14.11','sa','commentary','।।14.11।।एतच्च कार्योपलब्ध्यै वाऽवगच्छेदित्याह -- सर्वद्वारेष्विति। श्रोत्रादिषु अस्मिन् भोगायतने शब्दादिज्ञानात्मकः प्रकाश उपपद्यते? ज्ञानं च सुखं तदा सत्त्वं विवृद्धमिति जानीयात्। उतशब्दश्चार्थे लिङ्गेनेह विजानीयादित्युक्तम्।'),
('vallabhacharya-sc:source:14.12','Vallabhācārya','gita.14.12','sa','commentary','।।14.12।।लोभ इति। लोभस्तु कार्पण्यम्। प्रयोजनमनुद्दिश्यापि चलस्वभावता प्रवृत्तिः। आरम्भ उद्योगः कर्मणाम्।'),
('vallabhacharya-sc:source:14.13','Vallabhācārya','gita.14.13','sa','commentary','।।14.13।।अप्रकाश इति। अन्धतामिस्रं तामिस्रं महामोहो मोहश्चेति चतुर्धा। तमः पञ्चमं प्रथममेवोक्तम्। स्वरूपाज्ञाने हि (प्रवृद्धे विलोमतः) प्राणान्तःकरणेन्द्रियदेहाध्यासाः। इयं च पञ्चपर्वाऽविद्यैव नामान्तरेणोक्ता। श्रीविष्णुस्वामिप्रोक्ता तुता(स्वा)दृगुत्थविपर्यासभवभेदजभीषु च इति रूपाविभिन्नपर्याया? साऽप्यस्यामेव पर्यवस्यति। अत्राविद्या तमोगुणान्तर्भूता न पृथगुक्ता।'),
('vallabhacharya-sc:source:14.14','Vallabhācārya','gita.14.14','sa','commentary','।।14.14।।मरणसमये प्रवृद्धानां सत्त्वादीनां फलं गतिभेदमाह -- यदेति द्वाभ्याम्। सत्त्वे प्रवृद्धे तु प्रलयं गतो देही योगिनामुत्तमोपायविदां देहान्प्रपद्यते? अर्थात्तत्कुले भवति। तत्र जन्मवान् भूत्वाऽऽत्मयाथात्म्यज्ञानसाधनेषु पुण्यकर्मस्वधिकारी भवतीत्युक्तं उत्तमलोकान्वा प्राप्नोति।'),
('vallabhacharya-sc:source:14.15','Vallabhācārya','gita.14.15','sa','commentary','।।14.15।।रजसीति कर्मसङ्गिषु मध्यमलोकेषु जायते। तमसीति अधोयोनिषु नीचलोकेषु जायते।'),
('vallabhacharya-sc:source:14.16','Vallabhācārya','gita.14.16','sa','commentary','।।14.16।।अमरणसमये इह तु फलं सुकृतस्य सत्त्वेन कृतस्य कर्मणः पुण्यरूपस्य निर्मलं भवति दुःखगन्धरहितं अज्ञानादिगन्धरहितं च। रजसस्तु दुःखमज्ञानं तमसः कर्मणः फलं येन च पुनः पुनर्जन्ममरणपर्यावर्त्तेऽपि विवेकाभाव एव भवति। यद्यपिरजः कर्मणि [14।9] इति वाक्यात्कर्ममात्रसम्बन्धो राजस एव तथापि मतान्तररीत्याऽऽह -- कर्मणः सुकृतस्येति। सर्वमेव हि गौणम्। सत्त्वेन कृतस्य कर्मणः सात्त्विकस्य सुकृतपदवाच्यस्य फलमपि सात्त्विकं निर्मलं प्रकाशबहुलं भवति? सुखं चेत्याहुः कापिलाः।'),
('vallabhacharya-sc:source:14.17','Vallabhācārya','gita.14.17','sa','commentary','।।14.17।।तर्हि सत्त्वादिजनितं निर्मलादिफलं किं इत्यत्राह -- सत्त्वादिति। ज्ञानं वस्तुयाथात्म्यापरोक्षरूपं जायते। रजसस्तु स्वर्गादौ फले लोभः? तमसः पुनरनवधानमोहतत्त्वज्ञानाभावः।'),
('vallabhacharya-sc:source:14.18','Vallabhācārya','gita.14.18','sa','commentary','।।14.18।।तैर्गतिभेदमाह -- ऊर्ध्वं गच्छन्तीति। ब्रह्मलोकपर्यन्तमपि मोक्षं च। राजसास्तु मध्ये ततोऽधरस्थाने लोभस्य च तत्र निरूपितत्वात्। जघन्योऽधमो गुणस्तमोरूपः? तस्य वृत्तिः प्रमादमोहादिः? तत्र तेन वा स्थिता अधो गच्छन्ति। ततोऽधोभागरूपं जघन्यत्वेन निरूपितं स्थानमतलादि -- यथाऽसुराणां वैरोचनादीनाम् -- तत्र स्थितिः। नीचयोन्यादिषु वा नरकादौ यान्तीति।'),
('vallabhacharya-sc:source:14.19','Vallabhācārya','gita.14.19','sa','commentary','।।14.19 -- 14.20।।एवं गुणसर्गभेदोक्तौ पुरुषस्य सर्वस्य बन्धलीलामुपपाद्येदानीं तद्विवेकतो गुणात्ययद्वारा मोक्षलीलामाहू द्वाभ्याम् -- नान्यमिति। यदा गुणेभ्योऽन्यं कर्त्तारं नानुपश्यति गुणा एव स्वानुगुणप्रवृत्तिषु कर्त्तार,इति पश्यति गुणेभ्यश्च परमात्मानं वेत्ति तदा द्रष्टा मद्भावं ब्रह्माक्षरभावं प्राप्नोति ब्रह्मवित् (ब्रह्म वेद) ब्रह्मैव भवति [मुं.उ.3।2।9] इति श्रुतेः। निर्गुणं हि ब्रह्म स्वयमव्ययं तदा गुणांस्त्रीनेतानतीत्यामृतमश्नुते प्राप्नुते ब्रह्मसुखं वा भुङ्क्ते।'),
('vallabhacharya-sc:source:14.20','Vallabhācārya','gita.14.20','sa','commentary','।।14.19 -- 14.20।।एवं गुणसर्गभेदोक्तौ पुरुषस्य सर्वस्य बन्धलीलामुपपाद्येदानीं तद्विवेकतो गुणात्ययद्वारा मोक्षलीलामाहू द्वाभ्याम् -- नान्यमिति। यदा गुणेभ्योऽन्यं कर्त्तारं नानुपश्यति गुणा एव स्वानुगुणप्रवृत्तिषु कर्त्तार इति पश्यति गुणेभ्यश्च परमात्मानं वेत्ति तदा द्रष्टा मद्भावं ब्रह्माक्षरभावं प्राप्नोति ब्रह्मवित् (ब्रह्म वेद) ब्रह्मैव भवति [मुं.उ.3।2।9] इति श्रुतेः। निर्गुणं हि ब्रह्म स्वयमव्ययं तदा गुणांस्त्रीनेतानतीत्यामृतमश्नुते प्राप्नुते ब्रह्मसुखं वा भुङ्क्ते।'),
('vallabhacharya-sc:source:14.21','Vallabhācārya','gita.14.21','sa','commentary','।।14.21।।अथ गुणातीतस्य लक्षणमाचारं गुणात्ययहेतुं च जिज्ञासुरर्जुन उवाच -- कैर्लिङ्गैरिति। कैर्लक्षणैस्त्रीन् गुणानतीत उपलक्षितो भवति स किमाचारः कथं केनोपायेन हेतुरूपेण वा त्रीन् गुणानतिवर्त्तते इति।'),
('vallabhacharya-sc:source:14.22','Vallabhācārya','gita.14.22','sa','commentary','।।14.22।।तदा श्रीभगवांस्तत्स्वरूपमाचारं गुणातीततां च लक्षयन्नाह चतुर्भिः -- प्रकाशं चेत्यादिभिः। प्रकाशः सात्त्विकः? प्रवृत्ती राजसी? मोहस्तामस इत्येतानि त्रिगुणकार्याणि अनात्मसु प्रवृत्तानि न द्वेष्टि? यदि निवृत्तानि च तथापि न काङ्क्षति? अथवा प्रकाशं कर्माणि च निवृत्तानि न काङ्क्षति? कर्मप्रवृत्तिं मोहं च न द्वेष्टि? प्रवृत्तानि च कर्माण्यपीति।'),
('vallabhacharya-sc:source:14.23','Vallabhācārya','gita.14.23','sa','commentary','।।14.23।।उदासीनवदिति। गुणातिरिक्तात्मावलोकनतृप्तत्वात् अन्यत्रानात्मवस्तुनि उदासीनवदासीनः द्वेषाकाङ्क्षाद्वारेण गुणैश्च यो न विचाल्यते? किन्तु स्वकार्येषु प्रकाशादिषु गुणा वर्त्तन्त इति तिष्ठति न गुणानुगुणं स्वात्मना चेष्टते।'),
('vallabhacharya-sc:source:14.24','Vallabhācārya','gita.14.24','sa','commentary','।।14.24।।समेति। गुणकार्येषु हर्षद्वेषशून्यतया स लक्ष्य इत्युक्ते समत्वं योगो हेतुरिति साङ्ख्ययोगसारभूतमर्थं स्मारयति। समे दुःखसुखे रजस्सत्त्वकार्ये यस्य। तत्र हेतुः -- स्वस्थ आत्मस्थ इति। समानि लोष्टाश्मकाञ्चनानि हेयतया यस्य? सर्वत्र समभूतस्य।'),
('vallabhacharya-sc:source:14.25','Vallabhācārya','gita.14.25','sa','commentary','।।14.25।।मानापमानयोरिति। देहित्वप्रयुक्तसर्वारम्भपरित्यागी च यः? एवम्भूतः स गुणातीत उच्यते ज्ञानमार्गीयः।'),
('vallabhacharya-sc:source:14.26','Vallabhācārya','gita.14.26','sa','commentary','।।14.26।।किञ्च भक्तिमार्गीयस्य गुणातीतत्वं केवलगुणातीतभगवद्भक्त्येति तथाह -- मां चेति। मां पुरुषोत्तमं अव्यभिचारेण सर्वात्मना ऐकान्तिकेन भक्तियोगेन स्नेहयोगेन सेवते? स गुणानेतानतीत्य ब्रह्मभूयायाक्षरब्रह्मभावाय कल्पते। एतेन अव्यभिचारिभक्तिमर्यादया सेवतामपि ब्रह्मात्मप्राप्तिरुक्तानुषङ्गिकी अव्यभिचारिभक्तियोगोक्तिः। यथा च श्रुतौ -- यो वै स्वां देवतामतियजते प्रस्थायै देवतायै च्यवते न परीप्राप्नोति स पापीयान्भवति तमेवैकं जानथात्मानं अन्या वाचो विमुञ्चथ अमृतस्यैष सेतुः [मुं.उ.2।2।5] इति। अत्रात्मत्वेन ज्ञानं स्नेहभक्तिविषयत्वेन एवकारेण व्यभिचारिणीभक्तिव्यावृत्तिरनूद्यते अयमेवामृतस्य त्रिगुणात्मकरूपमोक्षस्य सेतुरित्यर्थः।'),
('vallabhacharya-sc:source:14.27','Vallabhācārya','gita.14.27','sa','commentary','।।14.27।।ब्रह्मभूयाय [14।26] इत्यादौ तत्र तत्र च निर्दिष्टानां ब्रह्मामृतधर्मसुखानां सर्वेषामभिन्न आश्रयोऽहमेवेत्याशयेन स्वस्य परत्वमाह -- ब्रह्मणो हीति। अक्षरस्य द्युभ्वाद्यायतनस्य ब्रह्मणोऽहं प्रतिष्ठा मूलस्थानं? तद्येन प्रतिष्ठितं वा सोऽहं ऐश्वर्यधामत्वात्तस्येत्यर्थः। अमृतस्य मोक्षस्य ब्रह्मानन्दस्याव्ययस्य च प्रतिष्ठाऽहं? तथा शाश्वतस्य सनातनस्य भगवद्धर्मस्य मोक्षार्थस्य तथैकान्तिकस्य भजनानन्दस्यागणितस्वरूपस्य क्षराक्षरातीतमत्स्वरूपात्मकस्याहमभिन्न आश्रयः? प्रतिष्ठा? तत्तत्पदैरहमेव तत्तदधिकारिणां तत्तद्भावनाविषयो वाच्यप्राप्य इत्यर्थः। एवं साङ्ख्यविवृतं स्वतात्पर्यवृत्त्येति ज्ञेयम्।'),
('vallabhacharya-sc:source:15.1','Vallabhācārya','gita.15.1','sa','commentary','।।15.1।।एवं पूर्वाध्याये पुरुषस्य प्रकृतिसम्बन्धो गुणसङ्गतो लीलार्थं भगवतैव कृतस्तारतम्यत इति पूर्वोक्तं साङ्ख्यं विवृतं? तत्प्रसङ्गाद्गुणविभागमुक्त्वाऽन्ते तन्निवृत्तिपूर्वकमक्षरब्रह्मात्मप्राप्तिः पुरुषोत्तमभक्ितमूला विरलस्य भक्तिमार्गीयस्य भवतीत्युक्तं इदानीं भजनीयस्य ब्रह्माद्याश्रयस्य मूलभूतस्य क्षराक्षरातीतपुरुषोत्तमस्य सर्ववेदान्ततात्पर्यभूतस्य क्षराक्षरात्मकबद्धमुक्तमूलभूततया सर्वधर्माश्रयत्वमुत्तमत्वं च वक्तुमारभते तत्र गुणसर्गेऽस्य सर्वस्य चिदचित्प्रपञ्चस्य नामरूपात्मकस्य भगवतः सच्चिदंशोद्भूतत्वाद्भगवत्स्वरूपस्य भजनीयतां तत्स्वरूपनिरूपणेन परिहरन् तन्मूलभूतस्य च तां प्रतिपादयन् श्रीभगवानुवाच -- ऊर्ध्वमूलमिति। ऊर्ध्वं ब्रह्मपर्यन्तं मूलं यस्य? यं विचित्रनामरूपप्रपञ्चाख्यं प्रसिद्धमश्वत्थं प्राहुः। भगवानपि तथा सोऽपि च।तेनेदं पूर्णं पुरुषेण सर्वं [श्वे.उ.3।9 म.ना.उ.8।14] इति वाक्यात् स भूमिं विश्वतो वृत्त्वाऽत्यतिष्ठद्दशांगुलम् [ऋक्सं.8।4।17।1] इत्यादिश्रुतेः। भगवान्मूलवृक्षरूपस्तस्माज्जगदपि जायमानं वृक्षात्मकमेव भवति। अनेन भगवतो महत्त्वं कारणत्वं च निरूपितम्।ऊर्ध्वमूलोऽवाक्शाखो यो(एषो)ऽश्वत्थः स सनातनः [कठो.6।11] ऊर्ध्वमूलावाक्शाखं वृक्षं यो वेद सम्प्रति इत्यादिश्रुतय आहुः। अश्वत्थादिवृक्षे एकस्मिन्कोटिशः फलानि भवन्ति तत्रैकस्मिन्फलेऽसङ्ख्यातानि बीजानीति एकस्य बीजस्यायं ब्रह्माण्डात्मको वृक्षः? सोऽपि तादृश एव। एवमनादिनिधनो वृक्षमूलो भगवानत एव क्वचिद्ब्रह्माण्डनिर्माणं भगवता स्वांशद्वारा क्वचित्तत्त्वद्वारा। अक्षरमत्र फलं तस्य तत्त्वान्यंशाः बीजं ब्रह्माण्डमिति? शकुनिभक्षि तमेव ततो निर्गतं फलतीति तत्त्वानां चेतनता निरूपिता।ऊर्ध्वमूलं इत्यादिविशेषणैर्विचित्ररचनत्वेन परमकाष्ठापन्नवस्तुकृतिसाध्यत्वात् तदंशत्वं तद्रूपत्वेन सनातनत्वं च सूच्यते। अतएवोक्तं यज्ञपत्न्युपाध्यायैःब्रह्मात्मकं ब्रह्मकार्यं वेदलोकमयं जगत् इतिप्रपञ्चो भगवत्कार्यस्तद्रूपो माययाऽभवत् इति भाष्यकारेण च। छंदासि यस्य भगवद्रूपप्रपञ्चस्य पर्णानि वायव्यं श्वेतमालभेत [यजुः2।1।1] स्वर्गकामो यजेत [आप.श्रौ.10।1।2।1] इत्यादिकानि छायासुखकराणि जीवानां भवन्ति? बाह्यतः काम्यकर्मपरत्वात्। आभ्यन्तरस्तुयन्न दुःखेन सम्भिन्नं तत्पदं स्वःपदास्पदम् इति व्यवस्थापनात्। यस्तमेवम्भूतमश्वत्थं वेद स वेदवित्। वेदो हि भगवत्कार्यभूते प्रपञ्चे अविद्यालिङ्गितजीवकृताहम्मत्वकल्पितकर्मादिपर्यावर्तसंसारविवर्तच्छेदोपायं वदति। अतएवसुवर्णजलवत्कार्यं इत्युक्तं श्रीमदाचार्यैः। तस्य चान्तरालिकस्य स्वरूपज्ञानं छेदनोपायज्ञानोपयोगीति वेदविदुच्यते।'),
('vallabhacharya-sc:source:15.2','Vallabhācārya','gita.15.2','sa','commentary','।।15.2।। किञ्च अधश्चेति। तस्य शाखास्थानीयतया सुकृतिनो दुष्कृतिनश्चोच्यन्ते। ताश्च सत्त्वादिभिर्गुणैः प्रवृद्धा विषयप्रवालाः शब्दादिविषयपल्लवाः। कथं इत्यत्राह -- अधश्च मूलानीति। ब्रह्मपदमूलकस्याधोऽस्मिन् लोके जटामूलान्यत्र वासनाख्यान्यनुसन्ततानि कर्मानुबन्धीनि। मानुष्यावस्थायां भारताजिरे हि स्वकृतैः कर्मभिरधो मनुष्यपश्वादय ऊर्ध्वं देवादयो भवन्तीत्यर्थः।'),
('vallabhacharya-sc:source:15.3','Vallabhācārya','gita.15.3','sa','commentary','।।15.3।।किञ्च न रूपमिति। इह मायामोहितैर्वादिभिरस्य स्वरूपं याथात्म्यं तथा वेदोक्तप्रकारेण नोपलभ्यतेमायामात्रं तु कात्स्न्र्येनानभिव्यक्तस्वरूपत्वात्। [ब्र.सू.3।2।3] किञ्च नान्तो निर्णयो न चादिः न च सम्प्रतिष्ठाऽपि। तेनासम्प्रतिष्ठमसत्यं स्वाज्ञानकल्पितं जगदुच्यते। वक्ष्यति च मायावादिनामासुराणां लक्षणेअसत्यमप्रतिष्ठं ते जगदाहुरनीश्वरम् [16।8] इति। ततो नेदं जगदसत्यं? किन्त्वेतदुपर्यावरणभूतं जीवकल्पितं सुवर्णजलवत्कार्यभूतसंसाराख्यं दुष्टांशमेनमभिन्नतया हंसोक्तितः प्रतीयमानम् अतएव सुतरां विरूढानि मूलानि,जीवकल्पितानि वासनामयानि दोषरूपाणि यत्र तमसङ्गशस्त्रेण दृढवैराग्यरूपेणाभजनीयतया सक्त्यभावेन छित्वा पृथक्कृत्य ततःपदमात्मरूपं भगवद्धामभूतमक्षरं ब्रह्म परिमार्गितव्यमित्यन्तरेणान्वयः। न चेह जीवकृतो जगदुच्छेद एव यथा श्रुतो वाच्योऽपि शिष्टत्वनिरूपणादिति वाच्यम्? उच्छेदिते दण्डे दण्डी पुरुषो नेतिवदविरोधात्।'),
('vallabhacharya-sc:source:15.4','Vallabhācārya','gita.15.4','sa','commentary','।।15.4।।तद्विशिनष्टि -- यस्मिन्निति। यत्र गता ज्ञानिनो भूयो न निवर्त्तन्ते। तत्र मुख्यं साधनं भक्तिमाह -- तमेव चाद्यं प्रपद्य इति। यतः पुराणी कृत्स्नस्य जगतः कर्मसु प्रवृत्तिरुत्पत्तिः प्रसृता भवति। तं प्रपद्य इति वा पाठः।'),
('vallabhacharya-sc:source:15.5','Vallabhācārya','gita.15.5','sa','commentary','।।15.5।।अन्यान्यपि साधनानि चाह -- निर्मानेति। मानमोहराहित्यं सङ्गदोषराहित्यं अध्यात्मज्ञाननित्यत्वं निवृत्तकामत्वं सुखदुःखादिद्वन्द्वरहितत्वं चेति। साधनसम्पन्नास्तद्विष्णोः परमं पदं सर्वदोषरहितं व्यापि वैकुण्ठात्मकमक्षरं ब्रह्माख्यं यान्तीत्यर्थः।'),
('vallabhacharya-sc:source:15.6','Vallabhācārya','gita.15.6','sa','commentary','।।15.6।।तदेव विशिनष्टि -- न तद्भासयत इति। तद्विष्णोः परमं पदं [ऋक्सं.1।2।6।5] अक्षरंचैद्ये च सात्वतपतेश्चरणं प्रविष्टे [ ] इति भागवतवाक्यात्पदभूतंप्रभुत्वेन हरेः स्फूर्तौ लोकवत्त्वेन तूद्भवः इति निबन्धवाक्यात् लोकात्मकत्वेन च प्रसिद्धं लोकप्रसिद्धाः सूर्यादयो न भासयन्ते यद्गत्वा च योगिनो नहि निवर्तन्ते तत्परमं सर्वोत्कृष्टं मम पुरुषोत्तमस्य धाम परमं ज्योतीरूपं सर्वप्रकाशकं अध्यात्मज्ञानस्वरूपंन यत्र माया इति निरूपणान्ममाधिष्ठानभूतं सर्वात्ममूलं निरुपममहिमात्मकं ज्ञेयम्।'),
('vallabhacharya-sc:source:15.7','Vallabhācārya','gita.15.7','sa','commentary','।।15.7।।अयमपि पुरुषो मे धाम ममैव सच्चिदानन्दात्मकस्य पुरुषोत्तमस्यैवांशोऽणुः केवलचिदात्मा स्वेच्छया पृथग्भावितः सनातनो वस्तुतो नित्यस्वरूपत्वात् -- अनादिकर्मरूपाविद्यावेष्टनतिरोहितानन्दस्वरूपो जीवभूतो जीवलोके वर्त्तमानो देवमनुष्यादिप्रकृतिपरिणामविशेषशरीरस्थानि मनष्षष्ठानीन्द्रियाणि कर्षति। कश्चित्पूर्वोक्तमार्गेणास्या अविद्याया मुक्तः स्वेन रूपेणावतिष्ठते संसारी जीवः अयं तु यतस्ततोऽतिसङ्कुचितज्ञानैश्वर्यः कर्मलब्धप्रकृतिपरिणामविशेषरूपशरीरस्थानामिन्द्रियाणां मनष्षष्ठानां कर्षणं कर्मानुगुणं करोति। सोऽप्यत्र ब्रह्मवादे सर्वशक्तिमतः पुरुषोत्तमस्यांश एव जीव इत्युच्यते। यथा च सूत्रेषुअंशो नानाव्यपदेशादन्यथा चापि दाशकितवादित्वमधीयत एके [ब्र.सू.2।3।43] इति। अयमात्मा भगवतोंऽशः सच्चिदानन्देषु चिद्रूपः इतरयोस्तत्र पराभिध्यानात्तिरोधानेन बन्धविपर्ययादिति क्रीडेच्छयैवांशत्वहेतुः। सूत्रे नानाव्यपदेशात् सर्व एवात्मनो (एत आत्मनः सर्वे प्राणाः सर्वे लोकाः सर्वे देवाः सर्वाणि भूतानि) व्युच्चरन्ति [बृ.उ.2।2।20] रमणीयचरणाः ৷৷. कपूयचरणाः [छां.उ.5।10।7] इति च। न च ब्रह्मणो निरवयवत्वात्कथं जीवोंऽश इति वाच्यम् न हि ब्रह्म निरंशं सांशं वा क्वचिल्लोके सिद्धं? वेदैकसमधिगम्यत्वात् सत्त्वाचार्यमतोपपन्नार्थतयाऽभ्युपगन्तव्यः? न तु सर्वविप्लवः कार्यः। युक्तिस्त्वेषोपपद्यते -- विस्फुलिङ्गा इवाग्नेर्हि जडा जीवाश्च निर्गताः। सर्वतः पाणिपादान्तात्सर्वतोक्षिशिरोमुखात्।।निरिन्द्रियात्स्वरूपेण तादृशादिति निश्चयः। संदेशेन जडाः पूर्वं चिदंशेनेतरा अपि।।अन्यधर्मतिरोभावा मूलेच्छातोऽस्वतन्त्रिणः इति हि ब्रह्मवादेंऽशपक्ष एव।ननु अंशत्वेन सजातीयत्वमायाति। श्रुत्यन्तरे पुनः ब्रह्म दाशा ब्रह्म दासा ब्रह्मेमे कितवा उत [ ] इत्यत्र सर्वस्यापि ब्रह्मज्ञानेन सर्वविज्ञानप्रतिपादनात् दाशादीनामपि ब्रह्मत्वं प्रतीयते तत्कार्यत्व एव स्यादिति चेत्? न? अन्यथा चापीत्यादि। प्रकारान्तरेणापि एके शाखिनः दाशकितवादित्वमधीयते शरीरत्वेनांशत्वेन च स्वरूपतः कार्याभावेऽपि प्रकारभेदेन कार्यत्वात्। तथा च न साजात्यं आनन्दाशस्य तिरोहितत्वात्। धर्मान्तरेण साजात्यं त्विष्टमेव ततोऽग्रे च सूत्रेमन्त्रवर्णात् [ब्र.सू.2।3।44] इति पुरुष एवेद्ँसर्वं [ऋक्सं.8।4।17।2यजुः31।2] इत्युक्त्वा पादोऽस्य विश्वा भूतानि [ऋक्सं.8।4।17।3यजुः31।3] इति जीवानां पादत्वं पादेषु स्थित्वेनावांशत्वम्। अतएवाग्रे अनुस्मर्यते इतिममैवांशो जीवलोके जीवभूतः सनातनः [15।7] इति।प्रकाशादिवन्नैवं परः [ब्र.सू.2।3।46] इत्यत्र च जीवस्यांशत्वं हस्तादिवत् तद्दुःखेन परस्यापि तदा दुःखित्वं स्यादिति चेत्? एवं परो न भवति एवमिति प्रकारभेदः द्विष्टत्वेनानुभव इति यावत्। अन्यथा सर्वरूपत्वात्। कुत एवं तत्राह -- प्रकाशादिवदितिनाग्नेर्हि तापो न हिमस्य तत्स्यात् इति प्रकाशग्रहणं धर्मत्वद्योतनाय सुखदुःखादयोऽपि ब्रह्मधर्मा इति। अतो द्वैतबुद्ध्यांशस्यैव दुःखित्वं? न परस्य।अथवा प्रकाशः प्रकाश्यदोषेण यथा न दुष्टः? तापस्यापि तदंशत्वादितिस्मरन्ति च [ब्र.सू.2।3।473।2।14] इति सूत्रे ऋषयोंऽशिनं स्मरन्ति? दुःखसम्बन्धं न स्मरन्तितत्र यः परमात्मा हि स नित्यो निर्गुणः स्मृतः। न लिप्यते फलैश्चापि पद्मपत्रमिवाम्भसा। इतिकर्मात्मा ह्यपरो योऽसौ मोक्षबन्धैः स युज्यते। एकस्तथा सर्वभूतान्तरात्मा न लिप्यते लोकदुःखेन बाह्यः [कठो.5।11] चकारात्तयोरेकं (अन्यः) पिप्पलं स्वाद्वत्ति अनश्नन्नन्यो अभिचाकशीति [मुण्ड.3।1।1] इति भाष्यात्। अतो जीवो नाम ब्रह्मांशो न तु ब्रह्मैव? कुतः,नानाव्यपदेशात्। श्रुत्यादौ एषोऽणुरात्मा चेतसा वेदितव्यः [मुण्ड.3।1।9] बुद्धेर्गुणेनात्मगुणेन चैव आराग्रमात्रो ह्यवरो(प्यवरो)ऽपि दृष्टः [श्वेता.5।8] इति। अत्र बुद्धेर्गुणेनावरः तिरोभूतानन्द आत्मगुणेन त्वाराग्रमात्र एव व्यापक इति व्याख्यातम्। न हि महतो ब्रह्मणोऽणुत्वं यत्र चाणुत्वं तज्जीवान्तर्याम्यभिप्रायेण। अतएव वालाग्रशतभागस्य [श्वेता.5।9] इत्यादौ तत्त्वमसि श्वेतकेतो [छां.उ.6।8।7816] योऽसावादित्ये सोसावहं [ ] यथाग्नेः क्षुद्रा [बृ.उ.2।1।20] इत्यादौ च नानाव्यपदेशात् सर्ववाक्यबाधाभावायाणुरेव ब्रह्मांश एव जीव इति मन्तव्यम्।अथवा नानाव्यपदेशात् भेदव्यपदेशादित्यर्थः। य आत्मनि तिष्ठन्नात्मानमन्तरे यमयति यमात्मा न वेद यस्यात्मा शरीरम् [श.ब्रा.14।5।30] इति माध्यन्दिनब्राह्मणे जीवपरमात्मनोर्भेदेनोपदेशात् केवलं प्राणधारणप्रयत्नवान् ब्रह्मणोंऽशो जीवशब्देनोच्यत इत्यर्थः। यो विज्ञाने तिष्ठन् विज्ञानमन्तरो यमयति [बृ.उ.3।7।22] इति काण्वपाठे स एवार्थः। एकत्र क्वचिदन्यथाप्रतिवादिना वक्तव्यं स्यात्? न तु नानाप्रमाणवचनेषु तथा अतएव श्रुतावभेदोक्तिः तदंशत्वात्। अंशत्वं स सजातीयत्वे सति तदपेक्षया किञ्चिन्न्यूनशक्त्याश्रयत्वमिति। स यथा महाराजो जानपदान् गृहीत्वा स्वे जनपदे यथाकामं परिवर्त्तत एवमेवायमात्मेति प्रज्ञया शरीरमुद्वह्य तमुत्क्रामति तयोर्ध्वमायन्नमृतत्वमेति [कठो.6।16छा.उ.8।6।6।] ऊर्णनाभिर्यथा तन्तून् सृजते सञ्चारत्यपि। जाग्रत्स्वप्ने तथा जीवो गच्छत्यागच्छते पुनः [ब्रह्मो.20] इति श्रुतिस्मृत्युक्तगमनागमनादिकं चाणुत्वमन्तरेण अनुपपन्नं जीवस्य ब्रह्मांशत्वमेव प्रबोधयतीत्यणुत्वाद्ब्रह्मणोंऽश एव जीवः। जीवब्रह्मविभागस्याविद्याकल्पितत्वे मानाभावात्अविभक्तं विभक्तिमत् इतिवाक्याच्छुतौ विश्वतश्चक्षुः [ऋक्सं.8।3।16।3] इतिमन्त्रे प्रयोजनाभावेऽप्युतेतिपदश्रवणात्मसहजो ब्रह्मकृत एवायं विभागः? न त्वविद्याकल्पितः तथा सति सृष्ट्यारम्भेऽविभक्तस्य संसारित्वाभावाद्विभागस्य च संसारकल्पनमन्तरेणानुपपत्तेरन्योन्याश्रयः प्रसज्येत। विभागस्याविद्याकल्पितत्वेन तस्याः स्थितेरनुक्तसिद्धत्वान्निराधारस्थितेरसम्भावितत्वाद्भ्रान्तिरूपत्वेन द्वैतापत्तिभिया च स्वाधिष्ठानत्वस्यापि वक्तुमशक्यत्वाद्ब्रह्मणश्चाधिष्ठानत्वे संसारित्वप्रसक्त्यैकमुक्तौ सर्वमुक्तिप्रसङ्गादभावदर्शनाच्छास्त्राप्रामाण्यं सर्वविप्लवप्रसङ्ग एव। तस्मादखिलश्रुतिस्मृतिप्रामाण्याज्जीवाः सर्वे भगवतो ब्रह्मणोंऽशा अणवः सनातनाः स्वेच्छातो विभक्ता इति सर्वमनवद्यम्। प्रकृते स एकोऽयं जीवभूतः यावन्तो जीवास्तद्रूपतया जातः। समष्ट्यभिप्रायेणैकवचनम्। स च जीवलोके प्रपञ्चे। प्रपञ्चो हि जीवानां लोको वैकुण्ठो भगवत इव। अतएव प्रपञ्चक्रीडने जीवरूपस्य प्राधान्यं अनेन जीवेनात्मना [छा.उ.6।3।2] इति श्रुतेः। तादृशोऽपि न देहादिरिवागन्तुकः? किन्तु सनातनः सर्वदैवैतावज्जीवरूपः न तु भौतिकसृष्टिवत्पश्चात्तनः। प्रपञ्चे तस्यांशस्य तथाभूतस्य कार्यमाह -- मनष्षष्ठानीति। मनसा षष्ठानि षण्णां पूरणानि षट्सङ्ख्याकानि इन्द्रियाणि ज्ञानेन्द्रियाणि वासनामयलिङ्गशरीरभूतानि विषयभोगोत्पत्त्यर्थं कृषीवलो भूमिमिव लिखति? इह विषयभोगोत्पत्यनुकूलानि करोतीत्यर्थः। तान्यपि प्रकृतिस्थानीति? नत्वात्मस्थानि। प्रकृतौ संसर्जनात्प्रकृतिस्थानीत्युक्तम्। अतएवोक्तंबुद्धीन्द्रियमनःप्राणान् जनानामसृजत्प्रभुः। मात्रार्थं च भवार्थं च स्वात्मने कल्पनाय च [भाग.10।87।2] इति तत एवायं जीवः।'),
('vallabhacharya-sc:source:15.8','Vallabhācārya','gita.15.8','sa','commentary','।।15.8।। शरीरं यदवाप्नोति। यस्माच्छरीरादुत्क्रामति तत्रायमिन्द्रियाणामीश्वरः एतानीन्द्रियाणि भूतसूक्ष्मैः सह गृहीत्वा संयाति। यथा वायुः कस्तूरिकाद्याशयात्तत्स्थानात्सूक्ष्मावयवैः सह गन्धान् गृहीत्वाऽन्यत्र संयाति तद्वत्। एतदेव प्रपञ्चितंउत्क्रान्तिगत्या गतीनां स्वात्मना चोत्तरयोः [ब्र.सू.2।3।1] इति सूत्रेषु।'),
('vallabhacharya-sc:source:15.9','Vallabhācārya','gita.15.9','sa','commentary','।।15.9।।तान्येवेन्द्रियाणि सेवते इति दर्शयन्यदर्थं गृहीत्वा गच्छति तदाह -- श्रोत्रमिति स्पष्टम्। प्राकृताहङ्कारकार्यं स्वस्वविषयवृत्त्यनुगुणं कृत्वा तत्तच्छब्दादीन् विषयानुपभुङ्क्ते।');
--> statement-breakpoint
INSERT INTO commentary_fts (unit_id,author,canonical_ref,language,content_type,content) VALUES
('vallabhacharya-sc:source:15.10','Vallabhācārya','gita.15.10','sa','commentary','।।15.10।।ननु तर्हि सङ्घाताद्भेदत एवम्भूतात्मानं किं न पश्यन्ति तत्राह -- उत्क्रामन्तमिति। विमूढा नानुपश्यन्ति तमेनं सत्त्वादिगुणमयप्रकृतिपरिणामविशेषमनुष्यत्वादिसंस्थानपिण्डसंसृष्टं पिण्डविशेषादुत्क्रामन्तं पिण्डविशेषेऽवस्थितं वा गुणमयान् विषयान् भुञ्जानं वा तद्गुणसारान्वितं वा प्रकृतिमयमनुष्यत्वादिपिण्डात्माभिमानिनो न पश्यन्ति। ज्ञानचक्षुषस्तु पिण्डात्मविवेकविषयज्ञानदृष्टयस्तु,सर्वावस्थमप्येनं विविक्ताकारमेव पश्यन्ति।'),
('vallabhacharya-sc:source:15.11','Vallabhācārya','gita.15.11','sa','commentary','।।15.11।।दुर्विज्ञेयश्चायं यतो विवेकिष्वपि केचित्पश्यन्ति केचिन्न पश्यन्तीत्याह -- यतन्त इति। योगिनश्चित्तवृत्तिनिरोधकाः पश्यन्ति? अन्ये तु यतन्तोऽप्यकृतचित्ता नैनं पश्यन्ति अतएवाचेतसो मन्दमतयः।'),
('vallabhacharya-sc:source:15.12','Vallabhācārya','gita.15.12','sa','commentary','।।15.12।।तदेवं सूर्यादीनां इन्द्रियसन्निकर्षविरोधिसन्तमसनिरसनमुखेनेन्द्रियानुग्राहकतया प्रकाशकानां ज्योतिष्मतामपि प्रकाशनिरपेक्षं सदानन्दचिद्रूपधामाक्षरः कालः प्रकृत्यध्यक्षः पुरुषश्चात्मा केवलचिद्रूपः जीवावस्थश्च भगवतो मे विभूतिरंश इत्युक्तम् इदानीमचित्परिणामविशेषोऽप्यादित्यादीनां पूर्वोक्तानां ज्योतिरादिर्मद्विभूतिरिति श्रौतार्थमाह -- यदित्यादिचतुर्भिः। आदित्यादिषु ममैवांशो तेजो यथा जीवलोके जीवभूत इति ब्रह्मवादेनाह। अंशभूतं तेजो विद्धि यत्तु योऽसावादित्ये पुरुषः सोऽसावहं [मैत्र्यु.6।35] इति श्रुतं? तत्तूपासनाभिप्रायेणाधिदैवतम्। एवं चन्द्रमस्यपि यदेष औषधीनामधिपतिः [ ] इति। आधिदैविकतया तैराराधिते वा मया तेभ्यो दत्तमिति च श्रूयते।'),
('vallabhacharya-sc:source:15.13','Vallabhācārya','gita.15.13','sa','commentary','।।15.13।।किञ्च सूर्यादिष्विव भूम्यादिष्वपि या धारणपोषणपाचनशक्तिः साऽपि मदीयेत्याह -- गामिति। ओजसा भुवमाविश्य भूतानि धारयामि तत्र धारणशक्तिर्मदंशतेजोभूता। पोषणशक्तिमाह -- सोम एव पुष्णामीति रसात्मकोऽमृतमयः सोमो भूत्वौषधीः व्रीह्याद्याः पुष्णामि। इदं च सोमोत्पत्तौ निरूपितम्।'),
('vallabhacharya-sc:source:15.14','Vallabhācārya','gita.15.14','sa','commentary','।।15.14।।किञ्च अहं वैश्वानर इति।वैश्वांनरः साधारणशब्दविशेषात् [ब्र.सू.1।2।24] इति सूत्रेषु श्रौतपदनिदर्शनार्थमुक्तम्। स्वस्यैव व्यापकतानिर्देशेन च नामरूपात्मतामाह -- वैश्वानरो वागधिपतिर्जाठरोऽहं? तत्र कार्यमाह पचामीति। तैर्भुक्तं भक्ष्यभोज्यलेह्यपेयात्मकं चतुर्विधमन्नं प्राणापाननिर्दिष्टव्यक्तिभेदसंयुक्तः पचामि। अत्र परमपुरुषविभूतिरूपाः सूर्यसोमवैश्वानरोऽहं रविः सोमोऽन्तर्वैश्वानरो भूत्वेति सामानाधिकरण्येन निर्दिष्टाः।'),
('vallabhacharya-sc:source:15.15','Vallabhācārya','gita.15.15','sa','commentary','।।15.15।।तेषां च सर्वभूतजातस्य परमपुरुषसामानाधिकरण्यनिर्देशे हेतुमाह -- सर्वस्येति। तेषा च सर्वभूतजातस्य चेति। सर्वस्य सकलप्रवृत्तिहेतुज्ञानोदयदेशे हृदि सर्वं स्वसङ्कल्पेन नियच्छन्नहमात्मतया सन्निविष्टः अन्तःप्रविष्टः शास्ता जनानां सर्वात्मा [चित्त्यु.11।2तै.आ.3।11] यः पृथिव्यां तिष्ठन् [बृ.उ.3।7।3] य आत्मनि तिष्ठन् [श.प.ब्रा.14।6] इत्यादिश्रुतेः। अतो मत्तः सर्वेषां स्मृतिः पूर्वानुभूतविषयसंस्कारमात्रजं ज्ञानं? ज्ञानमिन्द्रियलिङ्गागमयोगजो वस्तुनिश्चयः? सोऽपि मत्तः अपोहनं तयोः प्रमोषश्च मत्तः? ब्रह्मवादे स्वत एव सर्वसत्त्वात्। अपोहनमज्ञाननिवृत्तिरिति केचित्। यद्वा अपकृष्टमूहनं इदं प्रमाणमित्थं प्रवृर्त्तितुमर्हतीति प्रमाणप्रवृत्त्यर्हताविषयसामग्र्यादिनिरूपणजन्यं प्रमाणानुग्राहकं ज्ञानम्? तच्चापि मत्त एव। यतो वेदैश्च सर्वैरहमेव सर्वात्मना वेद्यः। ब्रह्मवादेऽग्निसोमसूर्यवाय्विन्द्रादीनां मदन्तर्यामिकत्वेन मद्रूपत्वात्तत्प्रतिपादनपरोऽपि वेदो मामेवाह सर्वम्।न च वेदान्तभूतैरुपनिषद्भिरेक एव प्रतिपाद्यते सर्वापवादमुखेनेति वाच्यम्? सर्वापवादमुखेन प्रतिपादनस्य जीवकल्पितत्वात्। न हि वेदान्तं सर्ववेदनिर्णयसिद्धान्तं मत्तोऽन्यः कोऽपि जानाति? मयैव कृष्णद्वैपायनात्मना ब्रह्मवादानुसारेण जीवकल्पिताध्यारोपवादनिरसनद्वारा तत्त्वनिश्चयादित्यर्थः। किमध्यारोपणमपोहनं च जीवकल्पितं न वा इति विचारणीयम्। अन्त्ये श्रुतिविरोधः? आद्ये इष्टापत्तिः? भगवत्कृतत्वे जगतः अलीकत्वस्यावचनीयत्वात्। विपरीतकल्पना च जीवकृतेति सिद्धान्तः? यत्तु माययैवेत्युच्यते तत्तु ब्रह्मवादे मायाऽपि न ततोऽन्यत्तत्त्वमिति समाधेयम्? सूत्रभाष्ये मायायाः पृथक्तया निरासनात्।आनुमानिकमप्येकेषामिति चेत् [ब्र.सू.1।4।1] इत्यादौ। तत्र चाव्यक्तस्यैवाक्षर इति नामोक्तम्। ब्रह्मवादे क्षरोऽक्षरस्तदतीत इत्येव स्वयं रमते स एव च सर्वशक्तिमान् स्वाज्ञाकारिणीं स्वतः पृथग्भावितां स्वीयमायां स्वभावकर्मसंज्ञां वा सदंशभूतां चिदंशभूतेषु क्षरेषु संयोजयति रमणार्थं? तदा प्रवाहः सिद्ध्यति अक्षरात्मत्वज्ञानतत्साधनशक्त्युदयनद्वारा रमणार्थं मर्यादा केवलं क्षराक्षरातीतस्वरूपप्रपञ्चेन रमणार्थं सृष्टेषु स्वप्रतिबिम्बभूतेषु तु भक्त्यात्मसु स नित्यं रममाण एवात्मारम इति पुष्टिरितिवेदान्तकृद्वेदार्थविदेव चाहं? नान्यः इत्युक्त्या मत्त एव सर्ववेदान्तानां सारमर्थं,शृण्विति पूर्वोक्तस्य सर्वस्य भाष्यमाभाष्यते भगवता भाष्यरूपत्त्वादस्याध्यायषट्कस्य।'),
('vallabhacharya-sc:source:15.16','Vallabhācārya','gita.15.16','sa','commentary','।।15.16।।द्वाविमाविति। लोके क्षरश्चाक्षर एव चेति पुरुषौ प्रथितौ? न स्त्रीप्रकृतिकौ? नाप्यत्रान्यतरो स्त्रीप्रकृतिकः? केवलजडप्रकृतिकश्च पुरुषत्वेनैवोभयोर्निर्देशात्। एतेनाव्यक्तपदवाच्यस्याक्षरस्य स्त्रीरूपप्रकृतित्वं परोक्तमपास्तंएव च इत्यनेन स्वरूपतः क्षरोऽक्षर एवेति सूच्यते। क्षरत्वं च भगवदिच्छया प्रकृतिसंसर्गोपाधिकृतमेव? अतो जायते म्रियते इति प्रवाहः न वस्तुतः। तदेतत्स्वयं व्याचष्टेक्षरः सर्वाणि भूतानि कूटस्थोऽक्षर उच्यते इति। सर्वाणि ब्रह्मादीनि स्तम्बपर्यन्तानि व्यष्टिभूतानि जीवशब्दाभिलपनीयानि भगवत्सदंशभूताचित्प्रकृतिसंसृष्टानि भवनादिक्रियाविषयत्वेन व्यपदिश्यमानानि क्षरः पुरुषः। अत्रैकत्वनिर्देशो व्यष्टीनां समष्ट्यैक्याशयेन अचित्संसर्गैकोपाधिना वेति केचित्। कूटस्थो मूलभूतः शुद्धः सच्चिदानन्दकः भगवद्धामादिपदवाच्योऽपि स महदादिषष्ठः कूटे भूतसमुदाये तिष्ठतीति वा। मूर्द्धन्यमणिरिव अविनाशी वाऽरेऽयमात्मा [बृ.उ.4।5।14] आत्मा वाऽरे द्रष्टव्यः श्रोतव्यो निदिध्यासितव्यः [बृ.उ.2।4।54।5।6] इत्याद्यौपनिषज्ज्ञानेन साक्षात्कृतो योऽक्षरः पुरुष इत्युच्यते अत्रैकत्वनिर्देशो विराट्समष्टिमूलभूताभिप्रायेण (धामत्वाभिप्रायेण)। तद्वियोगरूपैकोपाधिना वेति केचित्। अयमप्युक्तः पूर्वं मुक्त्याधिगम्यः।बहवो ज्ञानतपसा पूता मद्भावमागताः [4।10] इत्यत्राध्यात्मरूपः। वस्तुतस्तुचैत्यस्य तत्त्वममलं मणिमस्य कण्ठे [भाग.3।28।28] इति वाक्यात् कौस्तुभैक्यरूपेण मुख्यस्थितिरूप एवमुक्तिर्हित्वाऽन्यथारूपं स्वरूपेण व्यवस्थितिः इत्युच्यते इत्थं चावस्थानं भगवति दशमस्कन्धे भागवतेवीक्ष्यालकावृतमुखं [भाग.10।29।39] इत्यत्र श्रीमदाचार्यैर्दर्शितम्। एतेनैव क्षराक्षरस्वरूपनिरूपेण मतान्तरमपि प्रत्युक्तम्।'),
('vallabhacharya-sc:source:15.17','Vallabhācārya','gita.15.17','sa','commentary','।।15.17।।तदुत्तममाश्रयभूतं मुख्यं स्वरूपमाह (तदधिदैवतम्) उत्तमः पुरुषस्त्वन्य इति। तुशब्दः पूर्वतो भेदं दर्शयति। एताभ्यां अन्यो विलक्षणोऽमितसच्चिदानन्दात्मा पुरुषोत्तमः सर्वकारणकारणभूतः। निरस्तविकृतिरव्यय ईश्वरोऽद्भुतैश्वर्यो विभिन्नधर्माश्रय इति यावत्। स लोकत्रयं गुणात्मकमाविश्यान्तर्यामिरूपो भूत्वा बिभर्तीति ततः पुरुषोत्तम इत्युदाहृतः सर्वैः। यद्वा नन्वक्षरपरमपुरुषयोरपि भगवत्त्वात्को विशेषः तत्राह -- परमात्मेति। परमश्चासावात्मा चेति गङ्गाऽध्यात्मदेवतयोरिव तयोः स्वरूपमिति भावः। तथा च पुराणि स्वप्रकृतिकार्याणि अवराणि तत्सम्बन्धी क्षरस्तदुष्कृष्टोऽक्षरश्चराचरात्मा तदुत्तमः पुरुषोत्तम इति व्युत्पत्तिः? तेन नित्यबद्धमुक्तपुरुषद्वयाद्विलक्षणता दर्शिता।बद्धो मुक्त इति व्याख्या गुणतो मे न वस्तुतः [भाग.11।11।1] इति भागवतवाक्यात्। अस्यार्थः -- बद्ध इति क्षररूपतयाख्या आत्मनः मुक्त इत्यक्षररूपतया च विशेषाख्या मे गुणतः (सत्त्वरजस्तमोरूपात्। यद्वा) इच्छारूपाद्भवति तस्य मे मायामूलत्वात् मायां प्रति तस्य कारणत्वात्न मे मोक्षो न बन्धनं इति वैलक्षण्येन विरुद्धधर्माश्रयत्वमितिनहि विरध उभयं भगवत्यपरिगणितगुणगण ईश्वरेऽनवगाह्यमाहात्म्येऽर्वाचीनविकल्पवितर्कविचारप्रमाणाभासकुतर्कशास्त्रकलितान्तःकरणाश्रयदुरवग्रहवादिनां विवादानवसरः इति भागवतेनैव [6।9।36] सूत्रभाष्यरूपेण निर्णयात्।'),
('vallabhacharya-sc:source:15.18','Vallabhācārya','gita.15.18','sa','commentary','।।15.18।।एवम्भूतं पुरुषोत्तमत्वं स्वस्य निरुक्त्या स्वयं निर्दिशति -- यस्मादिति। क्षरमतिक्रम्येतः अक्षरादपि चोत्तम इति अतो लोके वेदे च प्रथितोऽहं पुरुषोत्तम इति पुरुषाभ्यां क्षराक्षराभ्यां उत्तम इत्येवं वेदे ब्रह्मविदाप्नोति परं [तै.उ.2।1] इति श्रुतौ लोके च माहात्म्यदर्शनात् अतः सच्चिदानन्दाकृतिरेवाहं परिदृश्यमानोऽपि? प्रतीत्यन्तरं तु माययेति सिद्धान्तः।'),
('vallabhacharya-sc:source:15.19','Vallabhācārya','gita.15.19','sa','commentary','।।15.19।।यतोऽहमेतादृशस्वरूपः सर्वोत्तमः पुरुषोत्तम इति अतः सज्ज्ञानवान् सर्वज्ञोऽन्यभजनरहितो मां भजतीत्याहुः -- यो मामिति। असम्मूढः सम्मोहस्यासुरत्वात्तद्रहितो यो मामजमनादिं पुरुषोत्तमं जानाति स सर्ववित् एकविज्ञानेन सर्वविज्ञानात्सर्वात्मभावेन मां भजति सेवत इति मार्गान्तराद्वैलक्षण्यं दर्शितम्।ज्ञानी चेद्भजते कृष्ण तस्मान्नास्त्यधिकः परः इति निबन्धेऽप्युक्तम्।'),
('vallabhacharya-sc:source:15.20','Vallabhācārya','gita.15.20','sa','commentary','।।15.20।।अध्यायार्थमुपसंहरति -- इतीति। इत्थं पुरुषोत्तमयोगकं शास्त्रं सर्ववेदान्तसारत्वाद्गुह्यतमं मया सर्ववेदान्तवेद्यचरणेन वेदान्तकृता पुरुषोत्तमेन त्वमनषतया योग्य इति तवोक्तं? अतएव तद्बुद्ध्वा बुद्धिमान्,शास्त्रतात्पर्यज्ञानवान् कृतकृत्यश्च स्यात् योऽपि कोऽपि। हे भारत त्वं कृतकृत्योऽसीति किमु वक्तव्यम् इति भावः।प्रपञ्चतः क्षराच्चाहमक्षरादपि चोत्तमः। भजनीय इति श्रीमान् स्वयं पञ्चदशेऽब्रवीत्।।1।।'),
('vallabhacharya-sc:source:16.1','Vallabhācārya','gita.16.1','sa','commentary','।।16.1 -- 16.3।।पूर्वाध्यायेयो मामेवमसम्मूढो जानाति पुरुषोत्तमम् [15।19] इत्युक्तं? तत्रबुद्धिर्ज्ञानमसम्मोहः इत्युक्तत्वादसम्मूढस्य दैवत्वं? तदितरस्य चासुरत्वमिति विभजन् पूर्वं दैवीं सम्पदमाह त्रिभिः श्रीभगवान् -- अभयमिति। एते षड्विंशतिगुणाः दैवीं सम्पदमभिजातस्य भवन्ति? देवसम्बन्धिनी दैवी। देवा भगवद्वचनानुवर्त्तिर्धमशीलास्तेषां सम्पत्साधनरूपा सामग्री सृष्टिर्वा? सा च भगवन्निगमधर्मानुवर्त्तिकैव? तामभिजातस्य दैवजीवस्य भवन्तीत्यर्थः।'),
('vallabhacharya-sc:source:16.2','Vallabhācārya','gita.16.2','sa','commentary','।।16.1 -- 16.3।।पूर्वाध्यायेयो मामेवमसम्मूढो जानाति पुरुषोत्तमम् [15।19] इत्युक्तं? तत्रबुद्धिर्ज्ञानमसम्मोहः इत्युक्तत्वादसम्मूढस्य दैवत्वं? तदितरस्य चासुरत्वमिति विभजन् पूर्वं दैवीं सम्पदमाह त्रिभिः श्रीभगवान् -- अभयमिति। एते षड्विंशतिगुणाः दैवीं सम्पदमभिजातस्य भवन्ति? देवसम्बन्धिनी दैवी। देवा भगवद्वचनानुवर्त्तिर्धमशीलास्तेषां सम्पत्साधनरूपा सामग्री सृष्टिर्वा? सा च भगवन्निगमधर्मानुवर्त्तिकैव? तामभिजातस्य दैवजीवस्य भवन्तीत्यर्थः।'),
('vallabhacharya-sc:source:16.3','Vallabhācārya','gita.16.3','sa','commentary','।।16.1 -- 16.3।।पूर्वाध्यायेयो मामेवमसम्मूढो जानाति पुरुषोत्तमम् [15।19] इत्युक्तं? तत्रबुद्धिर्ज्ञानमसम्मोहः इत्युक्तत्वादसम्मूढस्य दैवत्वं? तदितरस्य चासुरत्वमिति विभजन् पूर्वं दैवीं सम्पदमाह त्रिभिः श्रीभगवान् -- अभयमिति। एते षड्विंशतिगुणाः दैवीं सम्पदमभिजातस्य भवन्ति? देवसम्बन्धिनी दैवी। देवा भगवद्वचनानुवर्त्तिर्धमशीलास्तेषां सम्पत्साधनरूपा सामग्री सृष्टिर्वा? सा च भगवन्निगमधर्मानुवर्त्तिकैव? तामभिजातस्य दैवजीवस्य भवन्तीत्यर्थः।'),
('vallabhacharya-sc:source:16.4','Vallabhācārya','gita.16.4','sa','commentary','।।16.4।।आसुरीं सम्पदमाह -- दम्भ इति। दर्पः कामरूपः? अभिमानो लोभः। चकारैः पूर्वप्रतियोगिनो गृह्यन्ते स्पष्टमन्यत्। एते षट् दोषाः स्वभावतः पूर्वगुणवैरिण इति सर्वथा आसुरजीवस्य भवन्ति। भगवद्वचसि मायावादिनोऽसुराः भगवद्वचोऽननुवर्त्तिस्वभावा एव? अतोऽसुरा मापृस्ष्टाःत्रयः प्राजापत्याः ৷৷. देवा मनुष्या असुराश्च [बृ.उ.5।2।1] इति बृहदारण्यके। पञ्चरात्रेऽपि -- उत्पन्नास्त्रिविधा जीवा देवदानवमानवाः। तत्र देवा मुक्तियोग्या मानुषेषूत्तमा अपि।।अधमा मानुषा ये तु मृतियोग्याः पुनः पुनः। अधर्मा निरयायैव दानवास्तु तमोलयाः इत्युक्तम्। ये सम्भूतिमुपासते मायेत्यसुराः इति श्रुतिष्वपि।'),
('vallabhacharya-sc:source:16.5','Vallabhācārya','gita.16.5','sa','commentary','।।16.5।।उभयोः कार्यं दर्शयन्नाह -- दैवी सम्पदिति। विमोक्षाय विशेषतो मोक्षाय पुष्टिर्मयादाभेदेन निबन्धायासुरीति नितरां बन्धायाज्ञदुर्ज्ञत्वभेदेनेत्यर्थः। एतन्निशम्य स्वस्वभावानिर्द्धारादतिभीतमर्जुनं समाश्वासयति -- मा शुच इति। त्वं तु दैवीं सम्पदमभिजातोऽसि? पाण्डुर्हि देवस्वभावो देवांशत्वाद्धार्मिकत्वाच्च न तथा धृतराष्ट्र इत्यतः कार्यस्य हेतुसाम्यौचित्यात्पाण्डवेति सन्बोधयति।'),
('vallabhacharya-sc:source:16.6','Vallabhācārya','gita.16.6','sa','commentary','।।16.6।।द्वौ भूतसर्गाविति। अस्मिन् लोके देवमायांशानां भूतानां द्वौ सर्गौ दैव आसुरश्चेति।एव च इत्यनेनाधुना तु दैवेऽप्यासुरभावोदयकाल आयात इति द्योतयति। अत्रेदं तत्त्वमुक्तम् -- द्वौ भूतसर्गावित्युक्तेः प्रवाहोऽपि व्यवस्थितः। वेदस्य विद्यमानत्वान्मर्यादापि व्यवस्थिता। भक्तिमार्गस्य कथनात्पुष्टिंरस्तीति निश्चयः इति निर्हेतुकभगवदनुग्रहैकलभ्यतया व्रजस्थादिष्वन्तःकथनाद्भक्तिमार्गस्येति विवरणकृतां श्रीरघुनाथचरणानामाशयः। तत्र दैवो मर्यादयाऽत्रान्यत्र च विस्तरशः प्रोक्त एवेत्यतस्त्वमादौ मत्त आसुरं शृणु अवधारय।'),
('vallabhacharya-sc:source:16.7','Vallabhācārya','gita.16.7','sa','commentary','।।16.7।।सर्वात्मना वर्जनार्थमासुरीं विस्तरशो निरूपयति -- प्रवृत्तिमित्यादिद्वादशभिः। प्रवृत्तिमार्गं वेदोक्तं निवृत्तिमार्गं च न विदुरासुराःरुचिस्तेषां न कुत्रचित् इति श्रीमुखोक्तिरियम्। कुतः इत्यत आहन शौचं नापि चाचारो न सत्यं तेषु विद्यते इति मानसकायिकवाचिकदोषसद्भावेन सर्वत्र कर्मादौ तत्प्रतिपादकशास्त्रे च सत्यत्वानङ्गीकारादित्यर्थः।'),
('vallabhacharya-sc:source:16.8','Vallabhācārya','gita.16.8','sa','commentary','।।16.8।।किञ्चासत्यमिति।त्वमेक एवास्य सतः प्रसूतिःसत्यस्य सत्यं इति भागवतवाक्यात्,[10।2।2826] सदेव सोम्येदमग्र आसीत् [छां.उ.6।2।1] तत्सत्यमित्याचक्षते [तैत्ति.2।6] इत्यादिश्रुतेश्च। सत्यं परमकाष्ठापन्नसत्यवस्तुकृतिसाध्यत्वात्तदात्मकं जगदेतत्तदसुरा असत्यमाहुः मायास्वाज्ञानकल्पितत्वादियुक्तिभिः। तथासति तन्मध्यपातिवेदतदुदितसाधनानि व्यर्थानि स्युः? अनुपादेयानि च। न हि खपुष्पशशशृङ्गादिभिर्व्यवहार उपपद्यतेऽसत्त्वादित्यर्थः। तथाऽप्रतिष्ठं ब्रह्मणि न प्रतिष्ठा यस्य तथेति वदन्ति। अनीश्वरं च सत्यसङ्कल्पेन पुरुषोत्तमस्वरूपेण विभुना नियमितं न वदन्ति। मया तूक्तं -- अहं सर्वस्य प्रभवो मत्तः सर्वं प्रवृर्त्तते [10।8] इति।अहमेवात्मनाऽऽत्मानं सृजे हन्म्यनुपालये इति च। ते तु वदन्ति चैवम् -- अपरस्परसम्भूतं अपरस्परसम्भूतयोरन्योन्यसङ्गतयोः प्रकृतिरूपयोषित्पुरुषयोः परस्परसम्बन्धेन जातमिदं मनुष्यपश्वाद्युपलभ्यतेऽनेवम्भूतं किमन्यत् किञ्चिदपि नोपलभ्यत इति। अतः सर्वमिदं जगत्कामहैतुकमिति वदन्ति सहजासुराः।'),
('vallabhacharya-sc:source:16.9','Vallabhācārya','gita.16.9','sa','commentary','।।16.9।।एतां दृष्टिमिति। सर्वत्र मृषात्वदृष्टिं चावष्टभ्य स्वस्य ब्रह्मणोऽविद्यासम्बन्धतो जीवत्वादिमताङ्गीकारान्नष्टात्मानस्ते। वस्तुतोऽल्पबुद्धयः सर्वस्य जगतः क्षयाय प्रभवन्त्युद्भवन्ति। विष्णुपुराणे तूक्तं -- तदेतदक्षयं नित्यं जगन्मुनिवारिखलम्। आविर्भावतिरोभावजन्मनाशविकल्पवत् इत्यादि। तथाभूतस्यात्र क्षयायोद्भवन्ति।वर्त्तमानसामीप्ये वर्त्तमानवद्वा [अष्टा.3।3।131़] इति सूत्राद्भविष्यति वा वर्त्तमानप्रयोगः।'),
('vallabhacharya-sc:source:16.10','Vallabhācārya','gita.16.10','sa','commentary','।।16.10।।काममिति। मोहादसद्ग्राहान् गृहीत्वा असन् ग्राह आग्रहो येषु ते तान् ग्रन्थान्प्रसिद्धान् प्रवर्त्तन्ते अन्तर्भावितण्यर्थोऽयं प्रवर्त्तयन्ति। यद्वा असदाग्रहान्प्रति प्रवर्तन्ते यतो दम्भमानमदान्विताः। तथा न शुचि व्रतं येषां यद्वा पूर्ववद्धि व्रतित्वात् विष्णुव्यतिरिक्तव्रतित्वाच्च ते तथा। तथाचोक्तं भारते मोक्षधर्मेशास्त्रं ह्यबुद्ध्वा तत्वेन केचिद्वादबलाज्जनाः। ब्रह्मस्तेना निरारम्भा दम्भमोहव्रतानुगाः। नैर्गुण्यमेव पश्यन्तो न गुणाननुयुञ्जते। तेषां तमश्शरीराणां तम एव परायणम् इति।'),
('vallabhacharya-sc:source:16.11','Vallabhācārya','gita.16.11','sa','commentary','।।16.11।।चिन्तामिति। एतावदिति। कामोपभोग एव फलमिति निश्चिताः।'),
('vallabhacharya-sc:source:16.12','Vallabhācārya','gita.16.12','sa','commentary','।।16.12।।अतएव आशापाशशतैरिति।'),
('vallabhacharya-sc:source:16.13','Vallabhācārya','gita.16.13','sa','commentary','।।16.13।।इदमद्य मया लब्धं इति स्पष्टम्।'),
('vallabhacharya-sc:source:16.14','Vallabhācārya','gita.16.14','sa','commentary','।।16.14 -- 16.15।।किञ्चअसौ मया हतः इति अभेदमगृह्य।ईश्वरोऽहमस्मि मोदिष्ये इत्यज्ञानविमोहिताः।'),
('vallabhacharya-sc:source:16.15','Vallabhācārya','gita.16.15','sa','commentary','।।16.14 -- 16.15।।किञ्चअसौ मया हतः इति अभेदमगृह्य।ईश्वरोऽहमस्मि मोदिष्ये इत्यज्ञानविमोहिताः।'),
('vallabhacharya-sc:source:16.16','Vallabhācārya','gita.16.16','sa','commentary','।।16.16।।अनेकेति।अज्ञश्चार्द्धप्रबुद्धश्च ब्रह्माहमिति यो वदेत्। महानरकजालेषु पच्यते नात्र संशयः इति ब्रह्माण्डोक्तेः। दुर्ज्ञाः कामोपभोगेषु प्रसक्ता अशुचौ नरके पतन्ति।'),
('vallabhacharya-sc:source:16.17','Vallabhācārya','gita.16.17','sa','commentary','।।16.17।।आत्मसम्भाविता इति। नामयज्ञैर्नाममात्रयज्ञैर्यजन्ति ते दम्भेन तत्राप्यविधिपूर्वकम्।'),
('vallabhacharya-sc:source:16.18','Vallabhācārya','gita.16.18','sa','commentary','।।16.18।।अहङ्कारमिति। मां पुरुषोत्तमं सर्वेश्वरमिह लीलाकर्त्तारं सर्वत्र वर्त्तमानं चेतनात्मानं च द्विपन्तो भवन्ति इदमेव तेषु महदासुरलक्षणं पारुष्यम्।'),
('vallabhacharya-sc:source:16.19','Vallabhācārya','gita.16.19','sa','commentary','।।16.19।।तानहमिति। अतः सहजासुरान् नत्वावेशिनो मायाविन आसुरीष्वेव योनिषु पुनः पुनः क्षिपामि।'),
('vallabhacharya-sc:source:16.20','Vallabhācārya','gita.16.20','sa','commentary','।।16.20।।आसुरीमिति। मामप्राप्यैव दृष्ट्यादिनाऽप्यसम्बध्यैवाऽधमां गतिं यान्ति। एवकारेण मत्प्राप्त्युपायभूतसन्मार्गप्राप्तिरपि नास्ति तेषां कुतः पुनर्मत्प्राप्तिः ततोऽन्धन्तमो मायैवाधमगतिरित्युक्तम्।'),
('vallabhacharya-sc:source:16.21','Vallabhācārya','gita.16.21','sa','commentary','।।16.21।।एतदासुरभावत आत्मनाशे मूलं हेतुमाह -- त्रिविधमिति। अस्यासुरस्य भावस्य नारकस्य त्रिधा मतं द्वारं कामश्च लोभश्च क्रोधः? तस्मादेतत्त्रयं त्यजेदिति तन्त्रान्तरवाक्येनैकार्थयति कामः क्रोधस्तथा लोभ इतितस्मादेतत्त्रयं त्यजेत् इति हितोपदेशः।'),
('vallabhacharya-sc:source:16.22','Vallabhācārya','gita.16.22','sa','commentary','।।16.22।।त्यागे च विशिष्टं फलमाह -- एतैर्नरकद्वारभूतैरित्यर्थः।'),
('vallabhacharya-sc:source:16.23','Vallabhācārya','gita.16.23','sa','commentary','।।16.23।।कामादित्यागश्च शास्त्रोक्तस्वधर्माचरणां विना न भवतीत्याह -- य इति। सर्वःब्रह्मादयस्त्ववयवाः पुरुषोत्तमस्य इत्याज्ञाय देवयजनं हरिणा सदोक्तं इति शास्त्रविधिमुत्सृज्य कामकारतः अशास्त्रीयस्वच्छन्दश्रद्धातो वर्त्तते? न च सिद्धिं कामपि तत्त्वज्ञानाप्तिरूपामामुष्मिकीं वा समवाप्नोति सुखमैहिकमपि नाप्नोति? न च परां गतिमपि।'),
('vallabhacharya-sc:source:16.24','Vallabhācārya','gita.16.24','sa','commentary','।।16.24।।फलितमाह -- तस्माच्छास्त्रमिति। तस्मान्मयि दत्तचित्तः कर्म युद्धाख्यं शास्त्रविधानोक्तं स्वधर्मं कर्त्तुमर्हसि।स्वकर्मवृत्तिर्दैवस्य निवृत्तिर्नासुरोदयात्। इति दैवासुरविभागोऽयं षोडश ईरितः।।।।'),
('vallabhacharya-sc:source:17.1','Vallabhācārya','gita.17.1','sa','commentary','।।17.1।।पूर्वाध्यायान्तेयः शास्त्रविधिमुत्सृज्य वर्त्तते कामकारतः। न स सिद्धिमवाप्नोति न सुखं न परां गतिम् [16।23] इत्यनेन शास्त्रविधिमुत्सृज्य स्वच्छन्दश्रद्धातो वर्त्तमानस्य दैवासुरविभागोक्तिमुखेन प्राप्यतत्त्वज्ञानाप्तिरूपा न सिद्धिरित्युक्तं? तत्राऽऽर्जुनः पृच्छति -- अर्जुन उवाच ये शास्त्रविधिमुत्सृज्येति। त्यक्त्वा वर्त्तन्ते कामकारशब्दनिर्दिष्टया श्रद्धयाऽन्विताः तेषां निष्ठा का हे कर्षक किं सत्त्वमाहो रजस्तम इति तेषां सत्त्वविषयिणी सा रजस्तमोविषयिणी वा निष्ठा इति प्रश्नतात्पर्यम्।'),
('vallabhacharya-sc:source:17.2','Vallabhācārya','gita.17.2','sa','commentary','।।17.2।।एवं पृष्टः पुनरपि द्विविधेषु त्रिगुणविवेकेनैव शास्त्रीयश्रद्धादिस्वरूपमाह -- श्रीभगवानुवाच त्रिविधेति। देहाभिमान आसुरः? तद्वतामशास्त्रविधिमुत्सृज्याननुसृत्य वर्तमानानां उभयविधानां जीवानां सा स्वभावजेति। त्रिगुणमयं स्वभावमन्यथा कर्त्तुं शक्तं हि शास्त्रीयं विज्ञानं? तत्तूक्तानां नास्तीति कामकारपदवाच्या निष्ठैव केवलं पूर्वतनस्वभावजा। श्रद्धा सा त्रिविधा भवति सात्त्विकी राजसी तामसी चेति मत्तस्तां श्रृणु।'),
('vallabhacharya-sc:source:17.3','Vallabhācārya','gita.17.3','sa','commentary','।।17.3।।तथाहिसत्त्वानुरूपेति। अन्तःकरणधर्मत्वात्सत्त्वानुरूपा अन्तःकरणानुरूपा श्रद्धा भवति पूर्वसंस्कारानुगतमन्तःकरणं यादृशं तादृशी श्रद्धा येषां शास्त्रज्ञानरहितमन्तःकरणं तेषां श्रद्धाऽपि तथा येषां न तथा तेषां श्रद्धाऽपि न तथा परन्तु एतेन शास्त्रविधित्यागात्यागतो वर्त्तते न जीवेषु दैवासुरभावः प्रतीयत इत्यवोचाम श्रद्धा कामकारवृत्तिश्चास्तिक्यमतिरेवेति। सम्प्रदायविदः तेन गुणमयत्वमुपपद्यते यो यादृशश्रद्धः स एव सः? यतोऽयं पुरुषः श्रद्धामयः।'),
('vallabhacharya-sc:source:17.4','Vallabhācārya','gita.17.4','sa','commentary','।।17.4।।तत्र प्रथमानाह -- यजन्त इति। सात्त्विका सत्त्वश्रद्धाप्रकृतयः प्रामाणिकान्सात्त्विकान् देवान्यजन्ते। एवमन्यत्। तदेवमुक्तं भागवते [1।2।27]रजस्तमःप्रकृतयः समशीलान् भजन्ति वा इत्येते शास्त्रविधिमुत्सृज्य त्रिधा यजन्तो दैवा आसुराश्चोक्ताः।'),
('vallabhacharya-sc:source:17.5','Vallabhācārya','gita.17.5','sa','commentary','।।17.5।।तेष्वपि पूर्ववद्विशेषमाह -- अशास्त्रविहितमिति द्वाभ्याम्। शास्त्रीयं पूर्वमुक्तम्। ये तु जना शास्त्रविधिमुत्सृज्य कामकारतः येषां कामकार एव हेतुस्तत एव तपस्तप्यन्ते शम्बुकादिवत् तानासुरनिश्चयान् विद्धीत्युत्तरेणान्वयः।'),
('vallabhacharya-sc:source:17.6','Vallabhācārya','gita.17.6','sa','commentary','।।17.6।।एवं च कर्षयन्त इति। कृशं कुर्वन्तो मां च मदाज्ञोल्लङ्घनतोऽन्तश्शरीरस्थं अन्तर्यामिस्वरूपं कर्षयन्तो विदूरयन्तस्तान्निश्चयेनासुरान्विद्धीति। परनिपात ऐच्छिकः। आसुरो निश्चयो येषां तानिति वा।'),
('vallabhacharya-sc:source:17.7','Vallabhācārya','gita.17.7','sa','commentary','।।17.7।।अथ पुनरपि प्रकृतमेव शास्त्रीयेषु वैदिकेषु यागादिषु गुणभेदतोऽपि विशेषं प्रपञ्चयति लौकिकेषु त्वाहारमूलत्वात्सत्त्वादिवृद्धेरित्याह -- आहारस्त्विति। त्रिविधः प्रियः। तथा यज्ञस्तपो दानं चेति त्रितयं श्रौतशास्त्रीयं तेषां भेदमिमं वक्ष्यमाणं शृणु।'),
('vallabhacharya-sc:source:17.8','Vallabhācārya','gita.17.8','sa','commentary','।।17.8।।तत्र प्रथममाहाराः -- आयुरिति। सत्त्वगुणोपेतस्य सत्त्वमया आहाराः प्रिया भवन्ति। ते चायुर्विवर्द्धनाः -- सत्त्वोपलक्षितं ज्ञानं तदादिवर्द्धनाश्च। रस्याः मधुरसोपेताः स्नेहयुक्ताश्च? स्थिराः स्थिरपरिणामाः? हृद्या रम्यस्वरूपाः एवंविधा अन्नरूपा आहाराः सात्त्विकप्रियाः सत्त्वजनकाः प्रियाः सात्त्विकानां वा प्रियाः? क्षेमकरा इति तात्पर्यार्थः।'),
('vallabhacharya-sc:source:17.9','Vallabhācārya','gita.17.9','sa','commentary','।।17.9।।कट्विति। राजसस्य प्रियाः।'),
('vallabhacharya-sc:source:17.10','Vallabhācārya','gita.17.10','sa','commentary','।।17.10।।यातयाममिति। चिरकालावस्थितं तामसप्रियम्।'),
('vallabhacharya-sc:source:17.11','Vallabhācārya','gita.17.11','sa','commentary','।।17.11।।शास्त्रीययज्ञस्य च त्रैविध्यं त्रिभिः स्पष्टम् -- अफलेति।'),
('vallabhacharya-sc:source:17.12','Vallabhācārya','gita.17.12','sa','commentary','।।17.12।।Sri Vallabhacharya did not comment on this sloka.'),
('vallabhacharya-sc:source:17.13','Vallabhācārya','gita.17.13','sa','commentary','।।17.13।।Sri Vallabhacharya did not comment on this sloka.'),
('vallabhacharya-sc:source:17.14','Vallabhācārya','gita.17.14','sa','commentary','।।17.14।।तपसः सात्त्विकादिभेदं दर्शयितुं प्रथमं तावच्छरीरादिभेदमाह त्रिभिः देवेति। देवेत्यारभ्य मानसमुच्यते इत्यन्तं सुगमम्।'),
('vallabhacharya-sc:source:17.15','Vallabhācārya','gita.17.15','sa','commentary','।।17.15।।Sri Vallabhacharya did not comment on this sloka.'),
('vallabhacharya-sc:source:17.16','Vallabhācārya','gita.17.16','sa','commentary','।।17.16।।Sri Vallabhacharya did not comment on this sloka.'),
('vallabhacharya-sc:source:17.17','Vallabhācārya','gita.17.17','sa','commentary','।।17.17।।त्रिविधस्य तस्य तपसः सात्विकादिभेदेन त्रैविध्यमाह -- श्रद्धयेति त्रिभिः।'),
('vallabhacharya-sc:source:17.18','Vallabhācārya','gita.17.18','sa','commentary','।।17.18।।Sri Vallabhacharya did not comment on this sloka.'),
('vallabhacharya-sc:source:17.19','Vallabhācārya','gita.17.19','sa','commentary','।।17.19।।Sri Vallabhacharya did not comment on this sloka.'),
('vallabhacharya-sc:source:17.20','Vallabhācārya','gita.17.20','sa','commentary','।।17.20।।पूर्वप्रतिज्ञातं दानस्य त्रैविध्यमाह त्रिभिः -- दातव्यमिति। सुबोधार्थः।'),
('vallabhacharya-sc:source:17.21','Vallabhācārya','gita.17.21','sa','commentary','।।17.21।।Sri Vallabhacharya did not comment on this sloka.'),
('vallabhacharya-sc:source:17.22','Vallabhācārya','gita.17.22','sa','commentary','।।17.22।।Sri Vallabhacharya did not comment on this sloka.'),
('vallabhacharya-sc:source:17.23','Vallabhācārya','gita.17.23','sa','commentary','।।17.23।।एवं श्रुतिसिद्धानां यागतपोदानानां सत्त्वादिगुणभेदेन भेद उक्तः इदानीं तस्य श्रौतस्यैव यज्ञादेर्देशकालादिसम्पत्त्यभावेऽपि तत्सम्पत्तिप्रकारमाह -- तत्सदिति। ब्रह्मणः वेदस्य पुरुषोत्तमस्य च त्रिविधो नाम व्यपदेशः स्मृतो ब्रह्मवादिभिः भक्तैश्च।ओमित्येकाक्षरं ब्रह्म [18।13] इत्यादिभिरोमिति संज्ञा ब्रह्मणः। तदिति संज्ञा यतो वाचो निवर्तन्ते [तै.उ.2।4]आनन्दमात्रमिति यत् इत्यारभ्यततो न ज्ञायते तत् इत्यन्तादिवाक्यैः। सदिति च नाम ब्रह्मणःसद्ब्रह्मास्ति ब्रह्म इति च वेदवादिभिरित्येत्ित्रविधं सर्वत्र यज्ञादौ विनियुक्तं सर्वदेशकालादिसम्पत्तिसाधकमिति ज्ञापनाय पूर्ववृत्तमाह -- ब्राह्मणास्तेनेति स्पष्टम्। अन्ये तु यज्ञादेः प्रणवयोगेन तत्सच्छब्दनिर्देश्यतया च लक्षणमाहुः इति। तत्सत् इति त्रिविधोऽयं निर्देशो ब्रह्मणः परस्य शाब्दस्य चान्वयी स्मृतः ब्रह्मशब्देन ब्रह्मात्मकं सर्वमक्षरादिकमक्षरपदवाक्यादिकमत्रोच्यते। तत्तत्सत् इतिशब्दान्वितं भवति तत्र प्रयोगादावाद्यःप्रणवश्छन्दसामिव इति सम्मत्या प्रणवस्यान्वयः श्रौतनामसु विधितः प्रयुज्यमानतयातत्सत् इतिशब्दयोश्च तत्रान्वयः पूर्णभावप्रयोजकशक्त्या भवतीत्यर्थः। तेनतत्सत् इतिनिर्देशेन ब्रह्मणा वा ब्राह्मणा वेदास्त्रिकाण्डा यज्ञाश्च एकैकेन वा विहिताः विशेषेण हिता वा मया पुरा सर्गादावित्यर्थः। अत्र इत्युच्चारकतया ब्राह्मणाःतत् इति ब्रह्मपरतया वेदाःसत् इति तदर्थीयकर्मतया यज्ञाः कृता इति विवेचनीयमिति केचिदाहुः। वयं तु उच्चारकतया ब्राह्मणाः उच्चार्यतया वेदाः कार्यतया यज्ञा विहिताः पुरा वेदाधिकृतानामित्येव ब्रूमः।'),
('vallabhacharya-sc:source:17.24','Vallabhācārya','gita.17.24','sa','commentary','।।17.24।।त्रयाणामन्वयप्रकारं वदन्प्रथमंओं इत्यस्यान्वयप्रकारमाह -- तस्मादिति। स्पष्टम्।'),
('vallabhacharya-sc:source:17.25','Vallabhācārya','gita.17.25','sa','commentary','।।17.25।।तदिति। तत्पदवाच्यं हि ब्रह्म? तत्सवितुरितिसर्वः कः किं यत्तत्पदमनुत्तमं [13।149।93] इति भारतसहस्रनामोक्तेः ब्रह्मैव फलमिति लौकिकं यत्तत्फलमनभिसन्धायात्र ब्रह्मवाचिना तदितिशब्देन निर्देश्या यज्ञादिक्रियाः क्रियन्ते मोक्षकाङ्क्षिभिरेव। अन्यैस्त्वन्यथेति निर्णयः।'),
('vallabhacharya-sc:source:17.26','Vallabhācārya','gita.17.26','sa','commentary','।।17.26।।सदित्यस्यान्वयप्रकारं लोके शब्दव्युत्पत्तिसिद्ध्या दर्शयति -- सद्भाव इति। अस्तीति सत् तस्मिन्भावे। अत्र भावो नाम वस्तु अन्यथा तत्रान्वस्थितिः स्यात् तेनसद्भावः इत्यत्र सत्पदेनाविर्भूतं भावो वस्त्वित्यभिधीयते। साधुभावे साधुत्वे च सदिति प्रयुज्यते। प्रशस्ते कर्मणि च सतो व्यापकस्य ब्रह्मणः,सर्वत्वश्रवणादेव तथा तथा प्रयोगः सर्वत्रोपपद्यते।'),
('vallabhacharya-sc:source:17.27','Vallabhācārya','gita.17.27','sa','commentary','।।17.27।।किञ्च यज्ञ इति। तपसि दाने च स्थितिः सदिति चोच्यते। स्थादिधातुगणे भुवो व्यापकत्वं? तदनुकृञश्चेति यज्ञपत्युपाध्यायाः प्रोचुः। अतएवोक्तं -- सर्वेषामपि वस्तूनां भावार्थो भवति स्थितः। तस्यापि भगवानेष किमतद्वस्तु रूप्यताम् इति। तथा सति सत्पदं (श्रेयोवचनं) निष्ठावचनमुक्तम्। कर्म चैव तदर्थीयं सदुत्तममित्येवाभिधीयते। एतेनमां विधत्तेऽभिधत्ते मां [भाग.11।21।43] इति प्राक्तनकर्मसदाचारपरिपाटी दर्शिता।'),
('vallabhacharya-sc:source:17.28','Vallabhācārya','gita.17.28','sa','commentary','।।17.28।।किञ्च यज्ञादिकं हुतादिकं च यत्कृतं अश्रद्धया शास्त्रीयश्रद्धाराहित्येन तदसद्व्यर्थमित्यर्थः। कुतः न च तत्प्रेत्य नो इहेति उभयलोकसुखासाधकत्वादित्यर्थः।'),
('vallabhacharya-sc:source:18.1','Vallabhācārya','gita.18.1','sa','commentary','।।18.1।।अष्टादशे स्वगीतार्थस्त्यागन्यासविनिर्णयात्। सर्वधर्मान्परित्यज्य शरणे मोक्ष उच्यते।।1।।इह खलुसर्वकर्माणि मनसा सन्न्यस्यास्ते सुखं वशी [5।13]सन्न्यासयोगयुक्तात्मा [9।28] इत्यादिषु सन्न्यासशब्दोऽभिहितःत्यक्त्वा कर्मफलासङ्गं [4।20] इत्यादिषु त्यागशब्दश्च तत्र सन्न्यासत्यागशब्दयोरेकविषय एवार्थो विशेषो वा कश्चनेत्यवशेषिततत्त्वबुभुत्सयाऽर्जुन उवाच -- सन्न्यासस्येति। सन्न्यासस्य त्यागस्य च तत्त्वं पृथक् विवेकतो ज्ञातुमिच्छामि? संशयासुरनिरासार्थंमहाबाहो केशिनिषूदन इति सम्बोधयति।'),
('vallabhacharya-sc:source:18.2','Vallabhācārya','gita.18.2','sa','commentary','Sanskrit Commentary By Sri Vallabhacharya।।18.2।।तत्र त्यागसन्न्यासयोरैकार्थेऽपि विषयभेदेन विनिर्णयं मतान्तरोपन्यासेन दर्शयन्नुत्तरभाष्यं स्वयं श्रीभगवानुवाच -- काम्यानां कर्मणामिति। ज्योतिष्टोमेन स्वर्गकामो यजेत स पाप्मानं तरति स ब्रह्महत्यां योऽश्वमेधेन यजते पुत्रकामो यजेत इत्यादिकामोपनिबन्धेन वेदेन विहितानां सर्वेषां न्यासं स्वरूपतस्त्यागं सन्न्यासं कवयो योगिनो विदुः। ततोऽपि विचक्षणाः स्वरूपतः त्यागमसहमाना निपुणा भक्ताः सर्वकर्मफलत्यागं सर्वेषां नित्यनैमित्तिककाम्यानां तथाश्रुतानामपि कर्मणां श्रुतफलस्य त्याग एव मोक्षशास्त्रे त्यागशब्दार्थ इति प्राहुः। तत्रैतेषां मते सन्न्यासार्थः सम्यक् फलत एव? न स्वरूपत इत्यायाति।'),
('vallabhacharya-sc:source:18.3','Vallabhācārya','gita.18.3','sa','commentary','।।18.3।।एके त्वाहुस्त्याज्यं दोषवदिति। कर्ममात्रं हिंसादिदोषवत्त्वात्त्याज्यमित्येके साङ्ख्याः मनीषिण इति युक्तिदर्शनात् स्तौति। अपरे मीमांसका यज्ञदानतपःकर्म सफलमपि श्रुतत्वान्न त्याज्यमित्याहुः। भ्रान्ता अप्येते एकांशतः समीचीनाः? यतः कस्मिंश्चिदप्यंशे वेदं न परित्यजन्ति। यद्यपि पूर्वेऽपि न परित्यजन्ति तथापि आपाततः प्रतीतिमादैयवमुपन्यस्तम् वस्तुतस्तुकाम्यानां इत्युक्तेऽकाम्यानां विधानमित्यर्थादुक्तं भवतीति भावेन कवित्वं तेषूक्तम्। अग्रे चविचक्षणाः इतिदोषवत् इत्युक्तेऽदोषवत्कार्यमिति मनीषिता तत्रोक्तेति।'),
('vallabhacharya-sc:source:18.4','Vallabhācārya','gita.18.4','sa','commentary','।।18.4।।एवं हि श्रौतो निर्णयः? न तं निश्चिन्वन्तीति स्वयं निर्णयमाह -- निश्चयं श्रृण्विति। स एव त्यागोऽन्यथाकृतश्चेद्गौणो भवेदित्याह। त्रिविधः तामसो राजसः सात्त्विकश्चेति प्रकीर्तितः। उक्तश्लोके वा त्रिविधः कीर्त्तितः।मयि सर्वाणि कर्माणि सन्न्यस्य [3।30] इत्यत्र निराशीः कामशून्यः निर्मम इति फलकर्मणोर्ममतारहितः (भूत्वा) एवं मयि कर्माणि सन्न्यस्य समर्प्य तत्कर्तृत्वं मय्यनुसन्धायतदधीनशक्तिरिदं करोमि इति धिया कृतकर्मसु कर्त्तृत्वममत्त्वफलानां त्यागो यः स सन्न्यास इति।'),
('vallabhacharya-sc:source:18.5','Vallabhācārya','gita.18.5','sa','commentary','।।18.5।।मीमांसकमतमेकांशतोऽङ्गीकरोति -- यज्ञेति। यज्ञो वै विष्णुः [तै.सं.1।7।4शं.ब्रा.1।3।1] इति श्रुत्या भगवत्स्वरूपो यज्ञः? दानं देवतोद्देशेन द्रव्यविसर्जनात्मकं च? तथा तपः स्वधर्माचरणं तदेतद्भगवद्धर्मपदरूपं श्रौतं कर्म न त्याज्यं मुमुक्षुणाऽपि? अपित्वाप्रायणादन्वहं कार्यमेव वेदोक्तत्वादपि कर्त्तव्यं एकांशेऽपि वेदस्यापरित्यागनियमात्। ननु कुतोऽयं कर्त्तव्यत्वविध्युपदेशः इत्यत आह -- पावनानीति। यज्ञादीनि मनीषिणां यैर्मनीषिभिर्दोषवदित्युक्तं तेषामेव गुणाधायकमिति दोषवदित्यपास्तम्। अतएव भगवदीयेन युधिष्ठिरेणयक्ष्ये विभूतीर्भवतः [भाग.10।7।3] इत्यादेशमादाय कृतमेव पावनार्थत्वात्। एतच्च भगवदीयानां कर्म कर्त्तव्यं न कर्त्तव्यं वा इत्यादिवादसंवादोपन्यासपूर्वकं भाष्ये विस्तृतमिति नेह प्रपञ्च्यते।'),
('vallabhacharya-sc:source:18.6','Vallabhācārya','gita.18.6','sa','commentary','।।18.6।।एवं ब्रह्मवादिनां कर्तव्यत्वे प्राप्तेऽपि तु परन्तु सङ्गं स्वकर्तृत्वाभिनिवेशं गुणमयरोचनार्थानि फलानि चोक्तविधया त्यक्त्वा कर्तव्यानीति विचक्षणाभिमतं निश्चितं मे मतम्। उत्तमं चैतत्सर्वमतेष्वित्याह उत्तममिति।'),
('vallabhacharya-sc:source:18.7','Vallabhācārya','gita.18.7','sa','commentary','।।18.7।।कवीनां मतं दूषयति -- नियतस्येति। कामोपनिबन्धेनापि वेदेन नियन्त्रितस्य नियमविहितस्य तु कर्मणः स्वरूपतस्त्यागः सन्न्यासः कार्य इत्युक्तः कविभिः स नोपपद्यते? ब्रह्मवादिनां वैदिकानां क्वचिदप्यंशे वेदोक्तस्यापरित्यागात्। यदि मोहादज्ञानात्तामसात्तस्य वैदिकस्य कर्मणस्त्यागः श्रौतेन क्रियमाणः स्यात्तदा मोहहेतुकत्वात् स त्यागस्तामसः परिकीर्तितः? तमःकार्यभूतेन मोहेन जायमानत्वात्प्रमादमोहौ तमसो भवतः [14।17] इत्यादिवाक्यात् प्रत्यवायावहश्चेति पर्युपसर्गार्थः।'),
('vallabhacharya-sc:source:18.8','Vallabhācārya','gita.18.8','sa','commentary','।।18.8।।प्रसङ्गादेव राजसमप्याह -- दुःखमिति। नियतस्यैव यस्य परम्परया मोक्षसाधनभूतस्यापि दुःखात्मकद्रव्यार्जनसाध्ययज्ञात्मकतया बह्वायासरूपतया च त्यागो राजसः रजोहेतुकत्वाद्राजसं त्यागं कृत्वा तत्फलं ज्ञाननिष्ठालक्षणं न लभेत सत्त्वसञ्जातत्वाज्ज्ञानस्येत्यर्थः।'),
('vallabhacharya-sc:source:18.9','Vallabhācārya','gita.18.9','sa','commentary','।।18.9।।विचक्षणाभिमतं त्यागं सात्त्विकतयाऽऽह -- कार्यमिति। नित्यनैमित्तिकमहायज्ञादिवर्णाश्रमविहितं कर्म भगवदाज्ञया तदाराधनरूपत्वात् कर्तव्यमिति यत्क्रियते हेऽर्जुन शुद्धस्वरूप तदप्युक्तप्रकारेणेत्याह -- सङ्गं कर्मणि ममतां फलं च त्यक्त्वेति। स सात्त्विकः सत्त्वहेतुकत्वात्। एवमपि पुष्टिपुरुषोत्तमश्रयण(ग्रहण)मेव सर्वं सन्न्यस्य निर्गुणस्त्यागस्तदाज्ञापरिपालनरूप इत्याचार्याभिमतः।'),
('vallabhacharya-sc:source:18.10','Vallabhācārya','gita.18.10','sa','commentary','।।18.10 -- 18.11।।एवम्भूतस्य लक्षणमाह -- न द्वेष्टीति। सत्त्वसमाविष्टस्त्यागी बुद्धिमान् अकुशलं कर्मानिष्टफलकं? कुशले चेष्टस्वर्गादिफलके कर्मणि नानुषज्जते? त्यक्तात्मसुखातिरिक्तफलत्वात्? त्यक्तकर्तृत्वाच्च। अत्राकुशलं कर्म प्रमादिनमभिप्रेत्योक्तम् नाविरतो दुश्चरितान्नाशान्तो नासमाहितः। नाशान्तमानसो वापि प्रज्ञानेनैनमाप्नुयात् [कठो.2।24ना.प.9।19महो.4।69] इति दुश्चरिताविरतस्य प्रमादिनो ज्ञानतोऽप्यात्मसुखानवाप्तिश्रवणात्। अतः कर्मणि कर्तृत्वसङ्गफलानां त्यागः शास्त्रीयः? न तु स्वरूपतस्त्याग इति। तदाह -- नहीति। नहि ध्रियमाणदेहेन कर्माण्यशेषतस्त्यक्तुं शक्यन्त इत्यर्थे शक्यमव्ययम्। देहधारणार्थानां अशनपानादीनां तदनुबन्धानां च कर्मणावर्जनीयत्वात्? तदर्थं च महायज्ञादिकर्माप्यवर्जनीयमेव। तत्र यः तेषु यज्ञादिकर्मसु फलत्यागी -- फलेत्युपलक्षणं कर्तृत्वममतयोरपि -- स एष त्यागेनैकेऽमृतत्वमानशुः [महाना.8।14कैव.2] इत्यादौ त्यागीत्यभिधीयते।'),
('vallabhacharya-sc:source:18.11','Vallabhācārya','gita.18.11','sa','commentary','।।18.10 -- 18.11।।एवम्भूतस्य लक्षणमाह -- न द्वेष्टीति। सत्त्वसमाविष्टस्त्यागी बुद्धिमान् अकुशलं कर्मानिष्टफलकं? कुशले चेष्टस्वर्गादिफलके कर्मणि नानुषज्जते? त्यक्तात्मसुखातिरिक्तफलत्वात्? त्यक्तकर्तृत्वाच्च। अत्राकुशलं कर्म प्रमादिनमभिप्रेत्योक्तम् नाविरतो दुश्चरितान्नाशान्तो नासमाहितः। नाशान्तमानसो वापि प्रज्ञानेनैनमाप्नुयात् [कठो.2।24ना.प.9।19महो.4।69] इति दुश्चरिताविरतस्य प्रमादिनो ज्ञानतोऽप्यात्मसुखानवाप्तिश्रवणात्। अतः कर्मणि कर्तृत्वसङ्गफलानां त्यागः शास्त्रीयः? न तु स्वरूपतस्त्याग इति। तदाह -- नहीति। नहि ध्रियमाणदेहेन कर्माण्यशेषतस्त्यक्तुं शक्यन्त इत्यर्थे शक्यमव्ययम्। देहधारणार्थानां अशनपानादीनां तदनुबन्धानां च कर्मणावर्जनीयत्वात्? तदर्थं च महायज्ञादिकर्माप्यवर्जनीयमेव। तत्र यः तेषु यज्ञादिकर्मसु फलत्यागी -- फलेत्युपलक्षणं कर्तृत्वममतयोरपि -- स एष त्यागेनैकेऽमृतत्वमानशुः [महाना.8।14कैव.2] इत्यादौ त्यागीत्यभिधीयते।');
